global function integer gf_tz_dbzcl (string as_brbm, string as_jzkh, string as_jydd, ref string as_error);//====================================================================
// 事件: gf_tz_dbzcl()
//--------------------------------------------------------------------
// 描述: 自动处理单边账问题 
//--------------------------------------------------------------------
// 参数:
// 	value    	string	as_brbm 	  病人编码
// 	value    	string	as_jzkh 	  就诊卡号
// 	value    	string	as_jydd 	  交易地点
// 	reference	string	as_error	  错误文本
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2021.07.08     24949
//====================================================================
Long ll_row, ll_rowCount, ll_failCount=0, ll_jllsh
String ls_jsjylsh, ls_jllsh_msg, ls_jydd
Decimal{2} ldc_ylfyze
dateTime ldt_jssj
Integer li_TZYBDBZYS
dataStore lds_zfjyjl
str_yb_jsxx lstr_yb_jsxx
str_tzyb_jsxx lstr_tzyb_jsxx

IF gu_ybjk_public.is_ybkfs='EPTZ' THEN

	li_TZYBDBZYS = Integer(gf_GetPara(0, "TZYBDBZTS", "15", "台州医保单边账天数")) 

	lds_zfjyjl = create dataStore
	lds_zfjyjl.dataObject = 'd_pyyb_zfjyjl'
	lds_zfjyjl.setTransObject(sqlca)
	lds_zfjyjl.retrieve(as_brbm, li_TZYBDBZYS)
	ll_rowCount = lds_zfjyjl.rowCount()

	IF ll_rowCount>0 THEN

		IF base_info.syscode=10 or base_info.syscode=32 Then
			IF gu_ybjk_public.istr_yb_grjbxx.brxm <> gu_ybjk_public.iu_tzybjk.istr_yb_zhxx.str_tzyb_grjbxx.brxm Then
				IF gu_ybjk_public.uf_zhcx( as_jzkh, as_error)<0 Then
					gf_applog(" 作废状态反交易前，账户查询失败，JLLSH："+String(ll_jllsh)+" 失败原因："+as_error)
					return -1
				END IF
			END IF
		END IF

		For ll_row=1 to ll_rowCount Step 1
			IF base_info.syscode<>32 Then gf_waiting("该病人存在医保单边账问题，正在退费处理("+String(ll_row)+"/"+String(ll_rowCount)+")...", ll_row / ll_rowCount * 100)
			ll_jllsh = lds_zfjyjl.Object.jllsh[ll_row]       // 记录流水号
			ls_jsjylsh = lds_zfjyjl.Object.jsjylsh[ll_row]   // 结算交易流水号
			ldc_ylfyze = lds_zfjyjl.Object.fyze[ll_row]      // 费用总额
			ldt_jssj = lds_zfjyjl.Object.jssj[ll_row]        // 结算时间

//			IF base_info.syscode=10 Then
//				ls_jydd = 'MZYS'
//			ELSEIF base_info.syscode=41 Then
//				ls_jydd = 'FZHS'
//			ELSEIF base_info.syscode=5 Then
//				ls_jydd = gstr_jqxx.as_jqm
//				ls_jydd = 'MZSF'
//			ELSEIF base_info.syscode=32 Then
//				ls_jydd = gstr_jqxx.as_jqm
//				ls_jydd = 'ZZCX'
//			END IF

			IF gu_ybjk_public.uf_mzdbz_tfcl( as_jzkh, ls_jsjylsh, base_info.userid, ldc_ylfyze, as_jydd, ldt_jssj, lstr_tzyb_jsxx, lstr_yb_jsxx, as_error)<0 THEN
				ll_failCount++
				ls_jllsh_msg += String(ll_jllsh)+","
				gf_applog(" 作废状态反交易失败，JLLSH："+String(ll_jllsh)+" 失败原因："+as_error)
			END IF
		Next
		IF base_info.syscode<>32 Then gf_waiting("该病人存在医保单边账问题，正在退费处理("+String(ll_rowCount)+"/"+String(ll_rowCount)+")...", -1)

		IF ll_failCount>0 THEN
			ls_jllsh_msg = Left(ls_jllsh_msg, Len(ls_jllsh_msg) - 1)
			IF base_info.syscode<>32 Then Messagebox("提示", "部分医保单边账处理失败，请联系信息科处理！JLLSH："+ls_jllsh_msg)
		END IF

	END IF

END IF

Destroy lds_zfjyjl

return 1
end function

