private function string of_get_errormessage (string as_returncode);//====================================================================
// 函数: u_ybjk.of_get_errormessage()
//--------------------------------------------------------------------
// 描述:	根据错误代码返回错误描述
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_returncode	返回码
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2009.06.17
//====================================================================

//0	交易成功	无错误信息
//-1	系统错误（包括通讯错误）	有错误信息
//-200	未知错误	有错误信息
//-300	报文合法性错误	有错误信息
//-400	业务错误（不可执行的错误，碰到错误篋AT*
罅⒓赐顺龀绦颍
	有错误信息
//-500	业务错误（可执行的错误，程序运行完，最后返回相应的信息）	无错误信息，一般以交易结果信息返回


CHOOSE CASE Upper(as_returncode)
	CASE '-1'
		RETURN '系统错误（包括通讯错误）'

	CASE '-200'
		RETURN '未知错误'
	CASE '-300'
		RETURN '报文合法性错误'
	CASE '-400'
		RETURN '业务错误（不可执行的错误，碰到错误后立即退出程序）'
	CASE '-500'
		RETURN '业务错误（可执行的错误，程序运行完，最后返回相应的信息）'	
	case else
		return ''
END CHOOSE

end function

private function string of_numformat (decimal ad_datavalue, string as_datatype);//====================================================================
// 函数: u_ybjk.uf_numformat()
//--------------------------------------------------------------------
// 描述:	根据decimal数据格式类型，返回指定格式的字符串
//--------------------------------------------------------------------
// 参数:
// 	value	decimal	ad_datavalue	指定的数值
// 	value	string 	as_datatype 	指定的数值格式('da','db','dc','dd')				
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.8.3
//====================================================================
integer li_1 = 0
string ls_format
//'da','db','dc','dd','de','df','dg'
//,'dh','di','dj','dk','dl','dm','dn'
if isnull(ad_datavalue) then ad_datavalue = 0
choose case as_datatype
	case 'da','db','dc','dd','di','dh'//，2位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.00')
		else
			return string(ad_datavalue,'0.00')
		end if
	case 'de'//3位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.00')
		else
			return string(ad_datavalue,'0.00')
		end if
	case 'df','dg'//4位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.0000')
		else
			return string(ad_datavalue,'0.0000')
		end if
end choose


end function

public function date uf_getdate (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdate()
//--------------------------------------------------------------------
// 描述:	根据指定的譊AT*
(该字段必须为date类型)，返回接收到的值date
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  date
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================
//日期格式为YYYY-MM-DD

int li_find
string ls_datatype,ls_datavalue
li_find = ids_receive.find("dataname = '"+lower(as_name)+"'", 1, ids_receive.rowcount())
if li_find > 0 then
	ls_datatype = ids_receive.object.datatype[li_find]
	if ls_datatype = 'dtb' then
		ls_datavalue = trim(ids_receive.object.datavalue[li_find])
		if len(ls_datavalue)= 8 then
			ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,5,2) + "-" + mid(ls_datavalue,7,2)
		end if
	else
		gf_sblogmsg('数据类型不匹配,该函数只返回date类型('+as_name+')')
		setnull(ls_datavalue)
	end if
else
	gf_sblogmsg('字段名不存在('+as_name+')')
	setnull(ls_datavalue)
end if

return date(left(ls_datavalue,10))
end function

