public function decimal uf_getdecimal (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdecimal()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为decimal)，返回接受到的值decimal
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  decimal
//--------------------------------------------------------------------
// 作者:	sz		日期: 2009.06.17
//====================================================================

Int li_find
String ls_datatype,ls_datavalue
li_find = ids_receive.Find("dataname = '"+Lower(as_name)+"'", 1, ids_receive.RowCount())
IF li_find > 0 THEN
	ls_datatype = ids_receive.Object.DataType[li_find]
	IF ls_datatype >= 'da' And ls_datatype < 'dz' THEN
		ls_datavalue = ids_receive.Object.datavalue[li_find]
	ELSE
		gf_sblogmsg('数据类型不匹配,该函数只返回decimal类型('+as_name+')')
		SetNull(ls_datavalue)
	END IF
ELSE
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	SetNull(ls_datavalue)
END IF
RETURN Dec(ls_datavalue)

end function

