private function boolean of_receivein_data (string as_xxlx, string as_xxt, ref string as_return);//====================================================================
// 函数: u_ybjk.of_receive_data()
//--------------------------------------------------------------------
// 描述:	分解社保返回的消息
//--------------------------------------------------------------------
// 参数:
// 	value    	string	as_xxt   			社保直接返回的内容
// 	value    	string	as_xxlx  			消息类型
// 	reference	string	as_return	错误信息
//--------------------------------------------------------------------
// 返回:  boolean
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

String ls_mc[],ls_format[],ls_datavalue,ls_datatype,ls_xxt,ls_recieve,ls_xxfhm
Int li_len[],li_bound,li_i,li_sum,li_datarow,li_pos
Long ll_row,ll_find

//返回数据的判断
//if isnull(as_xxt) or trim(as_xxt) = '' then
//	as_return = '医保没有返回数据'
//	return false
//end if
ls_xxt = as_xxt
//如果没有错误就继续分解内部消息体内容
//ls_xxlx = ls_xxlx + "_O"
//this.of_get_structure( ls_xxlx,'JG', ls_mc, li_len, ls_format,as_return)
//li_bound = upperbound(ls_mc)
li_bound = This.of_get_jklx_count(as_xxlx , 'JG')
li_sum = 0
li_datarow = 0
DO WHILE Len(ls_xxt) > li_sum
	IF Trim(Mid(ls_xxt,li_sum+1)) = '' THEN
		RETURN True
	END IF
	li_datarow ++
	FOR li_i = 1 To li_bound
		ll_row = ids_receive_in.InsertRow(0)
		IF li_sum = 0 THEN
			li_pos = Pos(ls_xxt,"%%")
		ELSE
			li_pos = Pos(ls_xxt,"%%",li_pos + 2)
		END IF
		IF li_pos <= 0 THEN li_pos = Len(ls_xxt) + 1

		ls_datavalue = Trim(Mid(ls_xxt,li_sum + 1,li_pos - (li_sum + 1) )) //li_len[li_i]))

		ids_receive_in.Object.datavalue[ll_row] = ls_datavalue
		ids_receive_in.Object.datarow[ll_row] = li_datarow
		
		ids_receive_in.Object.DataType[ll_row] = This.of_get_jklx_format(as_xxlx, 'JG', li_i) //ls_format[li_i]
		ids_receive_in.Object.dataname[ll_row] = This.of_get_jklx_mc(as_xxlx, 'JG', li_i) //ls_mc[li_i]

		ll_find = ids_receive.Find("dataname = 'rowcount'",1,999999)

		IF ll_find <= 0 THEN ll_find = ids_receive.InsertRow(0)

		ids_receive.Object.datavalue[ll_find] = String(li_datarow)
		ids_receive.Object.DataType[ll_find] = 's'
		ids_receive.Object.dataname[ll_find] = 'rowcount'

		li_sum = li_pos + 1 //li_len[li_i]
	NEXT
LOOP
//ids_receive_in.saveas( "c:\receive_in.txt",text!,true)
RETURN True

end function

public function date uf_getdate_in (string as_name, long al_row);//====================================================================
// 函数: u_ybjk.uf_getdate()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date类型)，返回接收到的值date
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  date
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

//日期格式为YYYY-MM-DD
int li_find
string ls_datatype,ls_datavalue
li_find = ids_receive_in.find("Upper(dataname) = '"+Upper (as_name)+"' and datarow=" +string(al_row), 1, ids_receive_in.rowcount())

if li_find > 0 then
	ls_datatype = ids_receive_in.object.datatype[li_find]
	if ls_datatype = 'dtb' then
		ls_datavalue = trim(ids_receive_in.object.datavalue[li_find])
		ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,5,2) + "-" + mid(ls_datavalue,7,2)

	else
		gf_sblogmsg('数据类型不匹配,该函数只返回date类型('+as_name+')')
		setnull(ls_datavalue)
	end if
else
	gf_sblogmsg('字段名不存在('+as_name+')' + "行:" +string(al_row))
	setnull(ls_datavalue)
end if

return date(left(ls_datavalue,10))
end function

public function datetime uf_getdatetime_in (string as_name, long al_row);//====================================================================
// 函数: u_ybjk.uf_getdatetime()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date或datetime类型)，返回接收到的值datetime
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  datetime
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

Int li_find
String ls_datatype,ls_datavalue
DateTime ldt_datavalue
li_find = ids_receive_in.Find("Upper(dataname) = '"+Upper (as_name)+"' and datarow=" +String(al_row), 1, ids_receive_in.RowCount())

IF li_find > 0 THEN
	ls_datatype = ids_receive_in.Object.DataType[li_find]
	CHOOSE CASE ls_datatype
	//		case 'dt' //日期格式为YYYY-MM-DD HH:MM:SS
	//			ls_datavalue = trim(ids_receive.object.datavalue[li_find])
	//			return datetime(date(left(ls_datavalue,10)),time(right(ls_datavalue,8)))
		CASE 'dta' //日期格式为YYYYMMDD HHNNSS
			ls_datavalue = Trim(ids_receive_in.Object.datavalue[li_find])
			IF not IsNumber ( Mid(ls_datavalue,5,1) ) THEN
				ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,6,2) + "-" + mid(ls_datavalue,9,2) + " " + mid(ls_datavalue,12,2) + ":" + mid(ls_datavalue,15,2)+ ":" + mid(ls_datavalue,18,2)
			ELSE
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2) + " " + Mid(ls_datavalue,10,2) + ":" + Mid(ls_datavalue,12,2)+ ":" + Mid(ls_datavalue,14,2)
			END IF
			RETURN DateTime(Date(Left(ls_datavalue,10)),Time(Right(ls_datavalue,8)))
		CASE 'dtb' //日期格式为YYYYMMDD
			ls_datavalue = Trim(ids_receive_in.Object.datavalue[li_find])
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)))
		CASE ELSE
			gf_sblogmsg('数据类型不匹配,该函数只返回datetime类型('+as_name+')')
			SetNull(ls_datavalue)
			SetNull(ldt_datavalue)
			RETURN ldt_datavalue
	END CHOOSE
ELSE
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	SetNull(ldt_datavalue)
	RETURN ldt_datavalue
END IF



end function

public function decimal uf_getdecimal_in (string as_name, long al_row);//====================================================================
