String ls_datatype,ls_datavalue
li_find = ids_receive_in.Find("Upper(dataname) = '"+Upper (as_name)+"' and datarow=" +String(al_row), 1, ids_receive_in.RowCount())

IF li_find > 0 THEN
	ls_datatype = ids_receive_in.Object.DataType[li_find]
	IF ls_datatype >= 'da' And ls_datatype < 'dz' THEN
