public function integer of_splitparm (string as_parmstring, ref string as_parm[], string as_char);//功能：将以','作为分隔符的string型参数串as_parmstring分解成独立参数并放入变长数组
//      as_parm[](by ref)中.用于在窗口间传递多个参数
//参数：as_parmstring：以'as_char'作分隔符的多参数组成的字符串(要求原始的string型独立参数内不得含
//                     有','字符
//      as_parm[]：存放分解后的独立参数
//返回值：成功，返回变量个数；否则，返回 -1
//编制：张贤彬 7/13/1999
//修改：syc    2006-1-17
Integer li_finger,li_start = 1,li_counter
IF as_parmstring = "" THEN RETURN -1
li_finger = Posw(as_parmstring,as_char,li_start)
DO WHILE li_finger > 0
	li_counter ++
	as_parm[li_counter] = Midw(as_parmstring,li_start,li_finger - li_start)
	li_start = li_finger + 1
	li_finger = Posw(as_parmstring,as_char,li_start)
LOOP
IF li_start <= Lenw(as_parmstring) THEN
	li_counter ++
	as_parm[li_counter] = Midw(as_parmstring,li_start,Lenw(as_parmstring) - li_start +1)
END IF

RETURN li_counter

end function

