public function decimal of_get_zfbl (str_pyyb_zhxx astr_pyyb_zhxx, string as_ypzllb, string as_zxxmbm, string as_ywlb, string as_tsbbm, string as_dfybz, datetime adt_jfrq, ref integer ai_sfdj, ref string as_error);//====================================================================
// 事件: u_pyybjk_his.of_get_zfbl()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	str_pyyb_zhxx	astr_pyyb_zhxx	
// 	value    	string       	as_ypzllb     	
// 	value    	string       	as_zxxmbm     	
// 	value    	string       	as_ywlb       	
// 	value    	string       	as_tsbbm      	
// 	value    	string       	as_dfybz      	
// 	value    	datetime     	adt_jfrq      	
// 	reference	integer      	ai_sfdj       	
// 	reference	string       	as_error      	
//--------------------------------------------------------------------
// 返回:  decimal
//====================================================================

Dec{3} ldc_zfbl
This.uf_send_init('58')
this.uf_send_add('是否有医保卡',astr_pyyb_zhxx.klb)
this.uf_send_add('IC信息',astr_pyyb_zhxx.str_pyyb_grjbxx.kh)
This.uf_send_add('现金支付方式','1')
This.uf_send_add('银行卡信息','')
This.uf_send_add('药品诊疗类别',as_ypzllb)
This.uf_send_add('中心项目编码',as_zxxmbm)
This.uf_send_add('医疗待遇类别',astr_pyyb_zhxx.str_pyyb_grjbxx.cbrlb)
This.uf_send_add('业务类别',as_ywlb)
This.uf_send_add('疾病编码',as_tsbbm)
This.uf_send_add('单复方标志',as_dfybz)
This.uf_send_add('交易时间',String(adt_jfrq,'yyyymmdd'))
This.uf_send_add('医疗机构类型',is_yljglx)
IF uf_send(as_error) = True THEN
	IF This.uf_getstring('交易状态') <> '0' THEN
		as_error = This.uf_getstring('错误信息')
		RETURN -1
	END IF

	ai_sfdj = Integer( This.uf_getstring('收费等级'))
	ldc_zfbl = This.uf_getdecimal( '自付比例')
	RETURN ldc_zfbl
ELSE
	IF IsNull(as_error) THEN as_error = 'NULL'
	RETURN -1
END IF
RETURN -1
end function

