	IF itran_sqlca.SQLCode = 0 And itran_sqlca.SQLNRows > 0 THEN
		gf_commit_transaction(itran_sqlca)
		IF ii_smkjs = 1 THEN
			IF Not IsNull(astr_yb_jsxx.smkzhzfje) And astr_yb_jsxx.smkzhzfje <> 0 THEN
