public function integer uf_jycx (string as_jylx, string as_jylsh, ref string as_jyjd, ref str_pyyb_jsxx astr_pyyb_jsxx, ref string as_error);//1	是否有医保卡
//2	IC信息
//3	现金支付方式
//4	银行卡信息
//5	待查询用户交易类型号
//6	待查询的用户交易流水号
//30门诊结算、31挂号退号/门诊退费、32住院登记、36住院结算、37住院退费、40取消住院登记。
IF uf_set_instance(as_error ) < 0 THEN
	RETURN -1
END IF
ib_yd = false
This.uf_send_init( '43')
This.uf_send_add('是否有医保卡','0')
This.uf_send_add('IC信息','')
This.uf_send_add('现金支窪AT* ','')
This.uf_send_add('银行卡信息','')
This.uf_send_add('待查询用户交易类型号', as_jylx)
IF as_jylx = '36' OR as_jylx = '37' THEN
	long ll_jsdh
   SELECT jsdh Into :ll_jsdh From bqxt.zy_brry Where zyhm = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = '获取jsdh失败：' + itran_sqlca.SQLErrText
		RETURN -1
	END IF
	IF ll_jsdh > 1 THEN
		as_jylsh = as_jylsh + '-'+String(ll_jsdh)
	END IF
END IF
This.uf_send_add('待查询的用户交易流水号', as_jylsh)
// 	返回参数(RetMsg)
//1	交易状态
//2	错误信息
//3	写医保卡结果
//4	扣银行卡结果
//5	更新后IC卡数据
//6	用户交易是否成功
//7	交易时间
//8	交易结算流水号
//9	交易处于阶段 30，36三个交易分为,其余没有确认交易的则默认为空
//10	该用户交易出口参数
//11	基金分段信息结构体
//12	费用汇总信息结构体
//
IF This.uf_send( as_error) THEN
	IF This.uf_getstring("交易状态") <> '0' THEN
		as_error = This.uf_getstring("错误信息")
		RETURN -1
	ELSE
		IF This.uf_getstring("用户交易是否成功") <> '0' THEN
			as_error = "用户交易失败!"
			RETURN -1
		END IF
		astr_pyyb_jsxx.jsrq = This.uf_getdatetime( '交易时间')
		astr_pyyb_jsxx.jslsh = This.uf_getstring("交易结算流水号")
		IF as_jylx = '30' Or as_jylx = '31' Or as_jylx = '36' Or as_jylx = '37' THEN
//			of_get_ylfyzf(astr_pyyb_jsxx.str_yb_ylfyzf)
			IF as_jylx = '30' Or as_jylx = '36' THEN
				as_jyjd = This.uf_getstring("交易处于阶段") //0:已结算 1:已确认
				IF as_jyjd = '0' THEN
					as_jyjd = '0:已结算'
				ELSE
					as_jyjd = '1:已确认'
				END IF
			END IF
			of_get_ylfyzf(astr_pyyb_jsxx.str_yb_ylfyzf)
			astr_pyyb_jsxx.smkzhye  = astr_pyyb_jsxx.str_yb_ylfyzf.qtzfs3
			of_get_jjfd(astr_pyyb_jsxx.str_pyyb_jjfd)
		END IF
		//12	费用汇总信息结构体
	END IF
ELSE
	RETURN -1
END IF
RETURN 1


end function

