public function integer of_get_jzxlh (ref string as_jzxlh, integer ai_jslx, ref string as_error);Decimal{0} ll_Value
Long ll_Count
Long ll_Retry
//判断事务
IF uf_set_instance(as_error ) < 0 THEN
	RETURN -1
END IF
IF ai_jslx = 1 THEN
	Process_Begin:
	gf_begin_transaction(itran_sqlca)

	UPDATE GY_IDENTITY SET VALUE = VALUE + 1
		Where TNAME = 'PYYB_JZXLH' Using itran_sqlca;

	IF itran_sqlca.SQLCode <> 0 THEN // update失败，判断是否存在记录
		SELECT COUNT(*) INTO :ll_Count FROM GY_IDENTITY
			Where TNAME = 'PYYB_JZXLH' Using itran_sqlca;
		IF ll_Count > 0 THEN // 记录存在继续update(最多三次)
			ll_Retry ++
			IF ll_Retry >= 3 THEN
				GOTO Process_Error
			ELSE
				Gf_Rollback_Transaction(itran_sqlca)
				GOTO Process_Begin
			END IF
		ELSE // 记录不存在则插入新记录
			INSERT INTO GY_IDENTITY(TNAME,VALUE,ORIGIN_VALUE,INC_VALUE)
				Values ('PYYB_JZXLH',2013080101,2013080101,1) Using itran_sqlca;
			IF itran_sqlca.SQLCode <> 0 THEN GOTO Process_Error
			ll_Value = 2013080101
			GOTO Process_Success
		END IF
	ELSE
		SELECT COUNT(*) INTO :ll_Count FROM GY_IDENTITY
			Where TNAME = 'PYYB_JZXLH' Using itran_sqlca;
		IF ll_Count > 0 THEN
		ELSE // 记录不存在则插入新记录
			INSERT INTO GY_IDENTITY(TNAME,VALUE,ORIGIN_VALUE,INC_VALUE)
				Values ('PYYB_JZXLH',2013080101,1,1) Using itran_sqlca;
			IF itran_sqlca.SQLCode <> 0 THEN GOTO Process_Error
			ll_Value = 2013080101
			GOTO Process_Success
		END IF
	END IF

	SetNull(ll_Value)
	SELECT VALUE INTO :ll_Value FROM GY_IDENTITY
		Where TNAME = 'PYYB_JZXLH' Using itran_sqlca;

	IF IsNull(ll_Value)      THEN GOTO Process_Error
	IF ll_Value < 2013080101 THEN GOTO Process_Error

	Process_Success:
	gf_Commit_Transaction(itran_sqlca)
	as_jzxlh = String(ll_Value)
	RETURN 1

	Process_Error:
	gf_Rollback_Transaction(itran_sqlca)
	RETURN -1
ELSE
	SetNull(ll_Value)
	SELECT VALUE INTO :ll_Value FROM GY_IDENTITY
		Where TNAME = 'PYYB_JZXLH' Using itran_sqlca;
	IF IsNull(ll_Value)      THEN
		as_jzxlh = 'PYYB2013080101'
	ELSE
		as_jzxlh = 'PYYB' + String(ll_Value + 1)
	END IF
END IF

RETURN 1
