public function decimal of_get_zfbl (string as_cbrlb, string as_ypzllb, string as_zxxmbm, string as_ywlb, string as_tsbbm, string as_dfybz, date adt_jfrq, ref integer ai_sfdj, string as_jylx, ref string as_error);//====================================================================
// 事件: u_pyybjk_his.of_get_zfbl()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	string  	as_cbrlb 	
// 	value    	string  	as_ypzllb	
// 	value    	string  	as_zxxmbm	
// 	value    	string  	as_ywlb  	
// 	value    	string  	as_tsbbm 	
// 	value    	string  	as_dfybz 	
// 	value    	date	adt_jfrq 	
// 	reference	integer 	ai_sfdj  	
// 	reference	string  	as_error 	
//--------------------------------------------------------------------
// 返回:  decimal
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2013.04.17
//====================================================================

Dec{3} ldc_zfbl
//This.uf_send_init('58')
//this.uf_send_add('是否有医保卡','0')
//this.uf_send_add('IC信息','')
//This.uf_send_add('现金支付方式','1')
//This.uf_send_add('银行卡信息','')
//This.uf_send_add('药品诊疗类别',as_ypzllb)
//This.uf_send_add('中心项目编码',as_zxxmbm)
//This.uf_send_add('医疗待遇类别',as_cbrlb)
//This.uf_send_add('业务类别',as_ywlb)
//This.uf_send_add('疾病编码',as_tsbbm)
//This.uf_send_add('单复方标志',as_dfybz)
//This.uf_send_add('交易时间',String(adt_jfrq,'yyyymmdd'))
//This.uf_send_add('医疗机构类型',is_yljglx)
//Long ll_find
//CBRLB, YPZLLB, XMZXLSH, YWLB, DFBZ
Long ll_ret = -100
IF as_jylx = 'PT' THEN
	SELECT ZFBL,SFDJ INTO :ldc_zfbl,:ai_sfdj FROM jkxt.pyyb_fyypbl WHERE CBRLB = :as_cbrlb AND YPZLLB = :as_ypzllb AND
		XMZXLSH = :as_zxxmbm And YWLB = :as_ywlb And DFBZ = :as_dfybz Using itran_sqlca;

	IF itran_sqlca.SQLCode <> 0 And itran_sqlca.SQLCode <> 100 THEN
		as_error = '获取自付比例和收费等级失败' + itran_sqlca.SQLErrText
		RETURN -1
	END IF
	ll_ret = itran_sqlca.SQLCode
END IF

IF ll_ret = 100 Or as_jylx <> 'PT'  THEN
	//	IF as_jylx = 'TSB' THEN
	//		as_tsbbm = istr_yb_zhxx.str_pyyb_grjbxx.tsbbm
	//	ELSEIF as_jylx = 'MXB' THEN
	//		as_tsbbm = istr_yb_zhxx.str_pyyb_grjbxx.mxbbm
	//	END IF

	String ls_send,ls_recieve
	Long li_ret
	ls_recieve = Space(3000)
	//Long lt_1,lt_2
	//lt_1 = CPU()
	IF IsNull(as_tsbbm) THEN as_tsbbm = ''
	ls_send = "$$0~~~~1~~~~"+as_ypzllb+"~~" +as_zxxmbm + "~~"+as_cbrlb+"~~"+as_ywlb+"~~"+as_tsbbm+"~~"+as_dfybz+"~~"+String(adt_jfrq,'yyyymmdd')+"~~"+is_yljglx+"$$" //$$0~~0~~~~1~~~~"+as_ypzllb 	 	IF is_init_date <> String(Today(),'yyyymmdd') THEN 		IF Not of_yb_date_init(as_error,False) THEN
			as_error = 'f_UserBargaingInit初始化出错' + as_error
			RETURN -1
		END IF
	END IF
	//long ll_app1,ll_app2
	//ll_app1 = cpu()
	li_ret = f_UserBargaingApply(58,0,ls_send,ls_recieve,is_yljgdm)
	//ll_app2 = cpu()
	//gf_applog(string(ll_app1) + "医保交易apply:" +  string(ll_app2 - ll_app1))
	IF li_ret < 0 THEN
		as_error = String(li_ret)
		RETURN -1
	END IF
	ls_recieve = Mid(ls_recieve,3)
	ls_recieve = Mid(ls_recieve,1,Len(ls_recieve) - 2) //去掉$$开头以及结尾

	Integer li_pos
	li_pos = Pos(ls_recieve,"~~",1)
	IF Integer(Mid(ls_recieve,1,li_pos - 1) ) < 0 THEN
		as_error = Mid(ls_recieve,li_pos + 1 ,  Pos(ls_recieve,"~~",li_pos + 1) - li_pos - 1 )
		RETURN -1
	END IF
	//
	li_pos = LastPos(ls_recieve,"~~")
	String ls_return
	ls_return = Mid(ls_recieve,li_pos + 1)
	ldc_zfbl = Dec(ls_return)
	ls_recieve = Left(ls_recieve,li_pos - 2)
	li_pos = LastPos(ls_recieve,"~~")
	ls_return = Mid(ls_recieve,li_pos + 1)
	ai_sfdj = Integer(ls_return)
	IF as_jylx = 'PT' THEN
		gf_begin_transaction(itran_sqlca)
		INSERT INTO JKXT.PYYB_FYYPBL(CBRLB, YPZLLB, XMZXLSH, YWLB, DFBZ,ZFBL,SFDJ,XZSJ) VALUES
			(:as_cbrlb,:as_ypzllb,:as_zxxmbm,:as_ywlb,:as_dfybz,:ldc_zfbl,:ai_sfdj,SYSDATE) Using itran_sqlca;
		IF itran_sqlca.SQLCode <> 0 THEN
			as_error = '获取自付比例和收费礑AT* ' + itran_sqlca.SQLErrText
			gf_rollback_transaction(itran_sqlca)
			RETURN -1
		ELSE
			gf_commit_transaction(itran_sqlca)
