			//		VALUES (:ad_qsrq,'ZFXF',:as_brbm,:ad_zyh,:ad_zfje,:as_mxzdh,:as_smkjyh,:istr_yb_zhxx.str_yb_grjbxx.cbdxzqh,'',:as_ywlsh,:as_ywlx,0)
			Using itran_sqlca ;
	END IF
	IF itran_sqlca.SQLCode = 0 And itran_sqlca.SQLNRows = 1 THEN
		gf_commit_transaction(itran_sqlca)
		RETURN 0
	ELSE
		as_error = itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF
END IF

RETURN 1

end function

