private function boolean of_receivein_data (string as_xxlx, string as_xxt, ref string as_return, string as_mxnr);//====================================================================
// 函数: u_ybjk.of_receive_data()
//--------------------------------------------------------------------
// 描述:	分解社保返回的消息
//--------------------------------------------------------------------
// 参数:
// 	value    	string	as_xxt   			社保直接返回的内容
// 	value    	string	as_xxlx  			消息类型
// 	reference	string	as_return	错误信息
//--------------------------------------------------------------------
// 返回:  boolean
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

String ls_mc[],ls_format[],ls_datavalue,ls_datatype,ls_xxt,ls_recieve,ls_xxfhm
String ls_xxtcf
Int li_len[],li_bound,li_i,li_sum,li_datarow,li_pos = 0
Long ll_row,ll_find,ll_insert
Long ll_count
String ls_xxtfj[]
//返回数据的判断
//if isnull(as_xxt) or trim(as_xxt) = '' then
//	as_return = '医保没有返回数据'
//	return false
//end if
IF as_xxt = '' Or IsNull(as_xxt) THEN RETURN True
ls_xxt = leftw(as_xxt,lenw(as_xxt) - 1)
ll_count = of_splitparm(ls_xxt,ls_xxtfj,'^')
IF ll_count <= 0 THEN
	as_return = '未找到结构体^'
	RETURN False
END IF
//ls_xxt = as_xxt
//如果没有错误就继续分解内部消息体内容
//ls_xxlx = ls_xxlx + "_O"
//this.of_get_structure( ls_xxlx,'JG', ls_mc, li_len, ls_format,as_return)
//li_bound = upperbound(ls_mc)

li_bound = This.of_get_jklx_count(as_xxlx , 'JG')
li_sum = 0
li_datarow = 0

//加一条明细条数
ids_receive_in.InsertRow(1)
ids_receive_in.Object.datavalue[1] = '0'
ids_receive_in.Object.datarow[1] = 0
ids_receive_in.Object.dataname[1] = 'datacount'
ids_receive_in.Object.datamxnr[1] = as_mxnr
FOR ll_row = 1 To ll_count
	ids_receive_in.Object.datarow[1] = ll_row
	ls_xxtcf = ls_xxtfj[ll_row]
	FOR li_i = 1 To li_bound
		li_pos = posw(ls_xxtcf,'|')
		IF li_pos <= 0 THEN
			ls_datavalue = ls_xxtcf
		ELSE

			ls_datavalue = midw(ls_xxtcf,1,li_pos - 1)
			ls_xxtcf = midw(ls_xxtcf,li_pos + 1)
		END IF
		ll_insert = ids_receive_in.InsertRow(0)
		ids_receive_in.Object.datavalue[ll_insert] = ls_datavalue
		ids_receive_in.Object.datarow[ll_insert] = ll_row

		ids_receive_in.Object.DataType[ll_insert] = This.of_get_jklx_format(as_xxlx, 'JG', li_i) //ls_format[li_i]
		ids_receive_in.Object.dataname[ll_insert] = This.of_get_jklx_mc(as_xxlx, 'JG', li_i) //ls_mc[li_i]

		ids_receive_in.Object.datamxnr[ll_insert] = as_mxnr
		ll_find = ids_receive.Find("dataname = 'rowcount'",1,999999)

		IF ll_find <= 0 THEN ll_find = ids_receive.InsertRow(0)

		ids_receive.Object.datavalue[ll_find] = String(ll_row)
		ids_receive.Object.DataType[ll_find] = 's'
		ids_receive.Object.dataname[ll_find] = 'rowcount'
	NEXT
NEXT
//if base_info.userid='211240' then
//	ids_receive_in.saveas( "c:\receive_in.txt",text!,true)
//end if
RETURN True


end 
