public function integer uf_zydj (long al_zyh, string as_rylx, ref string as_jzbh, ref string as_error);//====================================================================
// 事件: u_sybjk_his.uf_zydj()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	long  	al_zyh  	
// 	value    	string	as_rylx 	
// 	reference	string	as_jzbh 	
