//使用临时事务
IF uf_set_instance(as_error) < 0 THEN
	RETURN -1
END IF

String ls_knsj
Long ll_ksdm,ll_count
DateTime ldt_ryrq,ldt_rysj,ldt_jsrq
String ls_zyhm,ls_bahm,ls_ysbm,ls_brch //,ls_kssj
String ls_grbh,ls_shsbkh,ls_xzqh,ls_ylbxkh
SELECT KNXX,BRKS,RYRQ,ZYHM,BRCH,BAHM,ZZYS,JSRQ
	INTO :ls_knsj,:ll_ksdm,:ldt_ryrq,:ls_zyhm,:ls_brch,:ls_bahm,:ls_ysbm,:ldt_jsrq
	From ZY_BRRY Where ZYH = :al_zyh Using gtrans_temp_mssql;
IF gtrans_temp_mssql.SQLCode <> 0 THEN
	as_error = '找不到对应的病人信息:' + gtrans_temp_mssql.SQLErrText
	RETURN -1
END IF

IF Not IsNull(ldt_jsrq) And Date(ldt_jsrq) > Date(1900,1,1) THEN
	ldt_ryrq = ldt_jsrq
ELSE
	SELECT BQRYSJ Into :ldt_rysj From ZY_BRRY_KZ Where ZYH = :al_zyh Using sqlca;
	IF Not IsNull(ldt_rysj) And sqlca.SQLCode = 0 THEN
		ls_knsj = istr_yb_grjbxx_syb.knsj
			ldt_ryrq = ldt_rysj
	END IF
END IF

return uf_zydj( ls_knsj, ll_ksdm, al_zyh, date(ldt_ryrq), ls_zyhm, ls_brch,ls_bahm, ls_ysbm, as_rylx , as_jzbh, as_error,itran_sqlca, true)

end function

