	ELSE
		This.uf_send_add('医疗类别','16') //0224调整：增加罕见病门诊16	
	END IF
	// 2020.10.26  CJN  9201 台州省异地和本院一样走新接口
	IF Left(as_knsj,6) = 'YBDZPZ' THEN
		ls_dkfs = '3' // 5.读卡方式(1) →  (3：令牌)
		as_knsj = Mid(as_knsj,7)
		IF of_splitparm( as_knsj, ls_ret, "|") >= 5 THEN
