public function integer uf_receive_ykt (string as_xxtlx, string as_brbm, string ls_ghsf, string as_recxxt, decimal adc_zfje, ref string as_error, ref str_yb_mzsfqq_new astr_yb_mzsfqq);This.uf_send_init(as_xxtlx)
string ls_receive,ls_error
long ll_pos,ll_pos2
integer li_ret
ls_receive = as_recxxt
ll_pos = Pos (ls_receive, '~~' , 1 )
IF ll_pos > 0 THEN
	li_ret = Integer(Mid(ls_receive,3,ll_pos - 3)) //		交易处理结果	数值型	4	是		0：成功 -1：失败
	IF li_ret = 0 THEN
		li_ret = 1
	ELSE
		ll_pos2 = Pos (ls_receive, '~~' , ll_pos + 1 )
		IF ll_pos2 = 0 THEN
			ll_pos2 = Len(ls_receive) - 2
		END IF
		ls_error = Mid(ls_receive,ll_pos + 1,ll_pos2 - ll_pos - 1) //		错误信息	字符型	200	否	

		IF IsNull(ls_error) THEN ls_error = ''
		as_error = '社保出错：代码' +String(li_ret) + ';'+ ls_error
		RETURN -1
	END IF
ELSE
	as_error = '社保出错：代码' +String(li_ret) + ';'+ ls_receive
	RETURN -1
END IF
if not this.uf_receive_data(ls_receive,as_error) then return -1

IF This.uf_getstring('交易处理结果') <> '0' THEN
	as_error = This.uf_getstring('错误信息')
	IF  This.uf_getstring('有误收费项目明细返回信息') > ''  THEN
		as_error = as_error + This.uf_getstring('有误收费项目明细返回信息')
	END IF
	RETURN -1
