//收费项目明细自负信螪AT*
	composite				只返回就医地上传的参考自负比例与参保地自负比例不一致的费用明细列表；详见下面收费项目明细自负信息结构体参数说明
//有误收费项目明细返回信息	composite				详见下面有误收费项目明细结构体参数说明
astr_yb_mzsfqq.str_yb_jsxx_syb.ywlx = 'SF'
//astr_yb_mzsfqq.str_yb_jsxx_syb.jslsh = This.uf_getstring('结算流水号')
String ls_jslsh,ls_yllb,ls_gdbdm
datetime ldt_now
ldt_now = gf_server_Date()
ls_jslsh = This.uf_getstring('结算流水号')
astr_yb_mzsfqq.str_yb_jsxx_syb.jslsh = ls_jslsh
astr_yb_mzsfqq.str_yb_jsxx_syb.gdbjsbz = This.uf_getstring('规定病结算标志')
astr_yb_mzsfqq.str_yb_jsxx_syb.jyjssj = This.uf_getdatetime( '交易结算时间')
IF Date(astr_yb_mzsfqq.str_yb_jsxx_syb.jyjssj) < Date(2000,1,1) THEN
	astr_yb_mzsfqq.str_yb_jsxx_syb.jyjssj = ldt_now
END IF
of_get_syb_jsxx(astr_yb_mzsfqq.str_yb_jsxx_syb)
istr_yb_jsxx_syb = astr_yb_mzsfqq.str_yb_jsxx_syb
IF adc_zfje <> astr_yb_mzsfqq.str_yb_jsxx_syb.grxjzf THEN
	as_error = '支付金额：' + String(adc_zfje) + ',结算'+String(astr_yb_mzsfqq.str_yb_jsxx_syb.grxjzf)+'的现金金额不一致'
END IF
astr_yb_mzsfqq.str_yb_jsxx_syb.jzbh =  ls_jslsh
astr_yb_mzsfqq.str_yb_jsxx_syb.jylsh =  ls_jslsh
