public function integer of_insert_bscfymx (long al_zyh, string as_ybjzbh, ref string as_msg);//====================================================================
// 事件: u_sybjk_his_tz.of_insert_bscfymx()
//--------------------------------------------------------------------
// 描述: 插入医保不上传项目明细到 sydyb_fymxsc 表中
//--------------------------------------------------------------------
// 参数:
// 	value    	long    	al_zyh   	
// 	value    	string  	as_ybjzbh	
// 	reference	String  	as_msg   	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2021.12.31    27471  28141  插入医保不上传项目明细到 tzyb_fymxsc_sbd 表中
//====================================================================
Long ll_row, ll_rowCOunt, ll_insert
ll_rowcount = ids_zyfymx.rowCount()

IF ii_YBBSCFYQY = 1 and ll_rowcount>0 Then 
	ids_ybfymx_sc.setTransOBject( itran_sqlca)
	ids_ybfymx_sc.reset()

	For ll_row=ll_rowcount to 1 Step -1
		IF gu_ybjk_public.of_judge_bscxm( ids_zyfymx.Object.yplx[ll_row], ids_zyfymx.Object.fyxh[ll_row], ids_zyfymx.Object.ypcd[ll_row], Ref as_msg) > 0 THEN
			ll_insert = ids_ybfymx_sc.InsertRow(0)
			ids_ybfymx_sc.Object.ZYH[ll_insert] = al_zyh
			ids_ybfymx_sc.Object.ywlx[ll_insert] = 'ZY'
			ids_ybfymx_sc.Object.YWLSH[ll_insert] = ids_zyfymx.Object.jlxh[ll_row]
			ids_ybfymx_sc.Object.fymxxh[ll_insert] = 0
			ids_ybfymx_sc.Object.zfbl[ll_insert] = 1.00
			ids_ybfymx_sc.Object.zfje[ll_insert] = ids_zyfymx.Object.zjje[ll_row] - ids_zyfymx.Object.yhje[ll_row]
			ids_ybfymx_sc.Object.zlje[ll_insert] = 0.00
			ids_ybfymx_sc.Object.hjzf[ll_insert] = ids_zyfymx.Object.zjje[ll_row] - ids_zyfymx.Object.yhje[ll_row]

			ids_ybfymx_sc.Object.xmyybh[ll_insert] = String(ids_zyfymx.Object.fyxh[ll_row] )
			ids_ybfymx_sc.Object.XMYYDMC[ll_insert] = String(ids_zyfymx.Object.fymc[ll_row])

			ids_ybfymx_sc.Object.ztbz[ll_insert] = 9  // 不上传明细的状态标志为9
			ids_ybfymx_sc.Object.SPBZ[ll_insert] = ids_zyfymx.Object.SPBZ[ll_row]
			ids_ybfymx_sc.Object.jzbh[ll_insert] =  as_ybjzbh

			ids_zyfymx.deleteRow(ll_row)
		END IF
	NEXT

	IF ids_ybfymx_sc.Update()=1 THEN
		COMMIT Using itran_sqlca;
	ELSE
		as_msg = "不上传明细保存失败：" + ids_ybfymx_sc.is_error
		ROLLBACK Using itran_sqlca ;
		return -1
	END IF
END IF

return 1
end function

