			RETURN DateTime(Date(Left(ls_datavalue,10)),Time(Right(ls_datavalue,8)))
		CASE 'dtb' //日期格式为YYYYMMDD
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)))


		CASE ELSE
			gf_sblogmsg('数据类型不匹配,该函数只返回datetime类型('+as_name+')')
			SetNull(ls_datavalue)
			SetNull(ldt_datavalue)
			RETURN ldt_datavalue
	END CHOOSE
ELSE
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	SetNull(ldt_datavalue)
	RETURN ldt_datavalue
END IF



