public subroutine uf_send_init (string as_xxtlx);//====================================================================
// 函数: u_ybjk.uf_send_init()
//--------------------------------------------------------------------
// 描述:	指明消息体类型，并清空datastore里的数据
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_xxtlx	消息体类型
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================
String ls_ip
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\YDZFMedInterface.dll' ) = False Or FileExists(gu_api.uf_getcurrentappdirectory()+'\webservice2.dll' ) = False THEN
	is_init_errormessage = '医保的动态链接库(' + gu_api.uf_getcurrentappdirectory()+ '\webservice2.dll 或YDZFMedInterface.dll)不存在，请先安装'
	ib_init_success = False
	RETURN
END IF
//判断ini是否存在，判断ip是否匹配
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\EPTradeCfg_YDZF.ini' ) = False  THEN
	is_init_errormessage = '医保的配置文件(' + gu_api.uf_getcurrentappdirectory()+ 'EPTradeCfg_YDZF.ini)不存在，请先安装'
	ib_init_success = False
	RETURN
ELSE
	ls_ip = ProfileString(gu_api.uf_getcurrentappdirectory()+"\EPTradeCfg_YDZF.ini", "WEBSERVICE",  "IP", "")
	IF is_pyybip <> ls_ip And is_pyybip1 <> ls_ip THEN
		is_init_errormessage = "数据库中医保前置机IP地址和EPTradeCfg_YDZF的WEBSERVICE的IP不匹配，请检查"
		ib_init_success = False
		//		MessageBox('提示',is_init_errormessage)
		RETURN
	END IF
END IF

IF uf_connect_sqlca_temp( ) < 0 THEN
	is_init_errormessage = is_error
	ib_init_success = False
	RETURN
END IF

IF is_init_date <> String(Today(),'yyyymmdd') THEN
	IF Not of_yb_date_init(is_error) THEN
		is_init_errormessage = 'f_Init初始化出错:' + is_error
		ib_init_success = False
		return
	END IF
END IF

Integer li_xhxh
SELECT JKXT.SEQ_SYB_BWID_PXXH.Nextval Into :li_xhxh From dual Using itran_sqlca;
is_jylsh = String(Today(),'yyyymmdd')+String(Now(),'hhmmss')+Right('0000'+String(li_xhxh),4)
ib_init_success = True
is_xxtlx = Lower(as_xxtlx)
ids_send.Reset()
ids_send_in.Reset()
ids_structre.SetFilter( '')
ids_structre.Filter( )
