//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2009.06.17
//====================================================================


IF IsNull(adt_datavalue) THEN
	RETURN ''
END IF
CHOOSE CASE as_datatype
	CASE 'dta' //格式YYYY-MM-DD HHMMSS
		RETURN String(adt_datavalue,'YYYY-MM-DD HH:MM:SS')

	CASE 'dtb' //格式YYYY-MM-DD
		RETURN String(adt_datavalue,'YYYY-MM-DD')

	CASE ELSE
		RETURN ''
END CHOOSE



end function

