public subroutine uf_send_init (string as_xxtlx);//====================================================================
// 函数: u_ybjk.uf_send_init()
//--------------------------------------------------------------------
// 描述:	指明消息体类型，并清空datastore里的数据
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_xxtlx	消息体类型
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2017-10-10
//====================================================================

//ib_yktdy = False
String ls_ip
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\BargaingApplyV3_01044.dll' ) = False THEN
	is_init_errormessage = '医保的动态链接库(' + gu_api.uf_getcurrentappdirectory()+ '\BargaingApplyV3_01044.dll)不存在，请先安装'
	MessageBox('提示',is_init_errormessage)
	ib_init_success = False
	RETURN
END IF
//判断ini是否存在，判断ip是否匹配
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\TradeCfgV3_01044.ini' ) = False THEN
	is_init_errormessage = '医保的配置文件(' + gu_api.uf_getcurrentappdirectory()+ '下的TradeCfgV3_01044.ini)不存在，请先安装'
	ib_init_success = False
	MessageBox('提示',is_init_errormessage)
	RETURN
ELSE
	ls_ip = ProfileString(gu_api.uf_getcurrentappdirectory()+"\TradeCfgV3_01044.ini", "SYSTEM",  "NativeAddress", "")
	IF is_tzybip <> ls_ip And is_tzybip1 <> ls_ip THEN
		is_init_errormessage = "数据库中医保前置机IP地址和TradeCfgV3_01044.ini的NativeAddress不匹配，请检查"
		ib_init_success = False
		MessageBox('提示',is_init_errormessage)
		RETURN
	END IF
END IF
ib_init_success = True

is_xxtlx = Lower(as_xxtlx)
ids_send.Reset()
ids_send_in.Reset()
ids_structre.SetFilter( '')
ids_structre.Filter( )

end subroutine

