	//		as_tsbbm = istr_yb_zhxx.str_pyyb_grjbxx.tsbbm
	//	ELSEIF as_jylx = 'MXB' THEN
	//		as_tsbbm = istr_yb_zhxx.str_pyyb_grjbxx.mxbbm
	//	END IF

	String ls_send,ls_recieve
