初始化出错' + as_error 			RETURN -1 		END IF 	END IF 	//long ll_app1,ll_app2
	//ll_app1 = cpu()
	li_ret = f_UserBargaingApply(58,0,ls_send,ls_recieve,is_yljgdm)
	//ll_app2 = cpu()
	//gf_applog(string(ll_app1) + "医保交易apply:" +  string(ll_app2 - ll_app1))
	IF li_ret < 0 THEN
		as_error = String(li_ret)
		RETURN -1
	END IF
	ls_recieve = Mid(ls_recieve,3)
	ls_recieve = Mid(ls_recieve,1,Len(ls_recieve) - 2) //去掉$$开头以及结尾

	Integer li_pos
	li_pos = Pos(ls_recieve,"~~",1)
	IF Integer(Mid(ls_recieve,1,li_pos - 1) ) < 0 THEN
		as_error = Mid(ls_recieve,li_pos + 1 ,  Pos(ls_recieve,"~~",li_pos + 1) - li_pos - 1 )
		RETURN -1
	END IF
	//
	li_pos = LastPos(ls_recieve,"~~")
	String ls_return
	ls_return = Mid(ls_recieve,li_pos + 1)
	ldc_zfbl = Dec(ls_return)
	ls_recieve = Left(ls_recieve,li_pos - 2)
	li_pos = LastPos(ls_recieve,"~~")
	ls_return = Mid(ls_recieve,li_pos + 1)
	ai_sfdj = Integer(ls_return)
	IF as_jylx = 'PT' THEN
		gf_begin_transaction(itran_sqlca)
