public function integer uf_zy_tfcl (string as_knsj, string as_jsjylsh, decimal adc_ylfyze, string as_zyhm, string as_czyxm, string as_jydd, datetime adt_jssj, ref str_tzyb_jsxx astr_tzyb_jsxx, ref str_yb_jsxx astr_yb_jsxx, ref string as_error);//wangyi 已改
//参保人员住院结算后若发现结算问题，需要通过退费交易处理。退费时生成负记录，重新结算时需重新上传明细。
//调用本交易将住院发生的结算数据通过产生负数方式取消，恢复为未出院状态（住院冻结），只有重新结算后卡才会被解冻。
String ls_klb
//,ls_knsj,ls_zyhm,ls_jzbh
//SELECT KNXX,ZYHM Into :ls_knsj,:ls_zyhm  From BQXT.ZY_BRRY Where ZYH = :al_zyh;
//IF SQLCA.SQLCode = 0 THEN
//	SELECT YBJZBH Into :ls_jzbh From ZY_BRRY_KZ Where ZYH = :al_zyh;
//END IF
ls_klb = '1'

IF Pos(istr_yb_zhxx.knsj,'|') > 0 or left(As_knsj,6) = 'YBDZPZ' THEN
	ls_klb = '5'
	as_knsj = istr_yb_zhxx.knsj
ELSE
	ls_klb = '1'
END IF
Long ll_jsdh
SELECT jsdh Into :ll_jsdh From zy_brry Where zyhm = :as_zyhm Using itran_sqlca;
IF itran_sqlca.SQLCode  = 100 Or itran_sqlca.SQLCode = 0 THEN
	IF ll_jsdh >= 1 THEN
		ll_jsdh = ll_jsdh + 1
		as_zyhm = as_zyhm + "-" + String(ll_jsdh)
	END IF
END IF
This.uf_send_init('37')
This.uf_send_add('是否有医保卡',ls_klb)
This.uf_send_add('IC信息',as_knsj)
This.uf_send_add('现金支付方式','1')
This.uf_send_add('银行卡信息','')
This.uf_send_add('要作废的住院结算交易号',as_jsjylsh)
This.uf_send_add('要作废的住院号',as_zyhm)
This.uf_send_add('操作员姓名',as_czyxm)
This.uf_send_add('终端机编号','0')

IF uf_send(as_error) = True THEN
	//1	交易状态	integer	4	是
	//2	错误信息	string	100	否
	//3	写医保卡结果	string	1	否
	//4	扣银行卡结果	string	1	否
	//5	更新后IC卡数据	string	300	否
	IF This.uf_getstring('交易状态') <> '0' THEN
		as_error = This.uf_getstring('错误信息')
		RETURN -1
	ELSE
		Integer li_cftf
		//6	是否为重复退费	int	1	否 0正常退费，1结算单在医保接口已经被退费过
		//			li_cftf = This.uf_getdecimal( '是否为重复退费')
		li_cftf = Integer(This.uf_getstring( '是否为重复退费'))
