public function integer uf_zy_tfcl (string as_knsj, string as_zyhm, string as_czyxm, string as_jydd, ref str_tzyb_jsxx astr_tzyb_jsxx, ref string as_error);//wangyi 已改
//参保人员住院结算后若发现结算问题，需要通过退费交易处理。退费时生成负记录，重新结算时需重新上传明细。
