//SELECT ZY_BRRY_KZ.YBJZBH Into :ls_jzbh From ZY_BRRY_KZ,ZY_BRRY Where ZY_BRRY.ZYH = ZY_BRRY_KZ.ZYH AND ZY_BRRY.ZYHM = :as_zyhm;
