Long ll_zyh,ll_jsdh
DateTime ldt_jssj
SELECT zyh,jsdh Into :ll_zyh,:ll_jsdh From zy_brry Where zyhm = :as_zyhm Using itran_sqlca;
SELECT jssj,qrjylsh Into :ldt_jssj,:ls_jsjylsh From JKXT.tzyb_JSMX Where zyh =  :ll_zyh And  qrjylsh Is Not Null And ztbz In (1,2) Using itran_sqlca;

