	//1	交易状态	integer	4	是
	//2	错误信息	string	100	否
	//3	写医保卡结果	string	1	否
	//4	扣银行卡结果	string	1	否
	//5	更新后IC卡数据	string	300	否
	IF This.uf_getstring('交易状态') <> '0' THEN
		as_error = This.uf_getstring('错误信息')
		RETURN -1
	ELSE
		Integer li_cftf
		//6	是否为重复退费	int	1	否 0正常退费，1结算单在医保接口已经被退费过
		li_cftf = Integer(This.uf_getstring( '是否为重复退费'))
		IF li_cftf = 0 THEN
		ELSE
			as_error = '结算单在医保接口已经被退费过'
		END IF
		//7	退费交易流水号	string	20	否
		//8	退费交易结算日期	datetime	20	否
		//9	退费计算结果信息	composite	 	否
		//10	基金分段信息结构体	composite	否
		//ADD BY SXL 2015-12-25
		//			11	市民卡账户支付退款金额	Double	10（2）	否		
		//			12	市民卡清算日期	String	8	否		Yyyymmdd
		//			13	市民卡交易流水号	String	20	否		

		astr_tzyb_jsxx.str_yb_grjbxx = This.istr_yb_zhxx.str_tzyb_grjbxx
		astr_tzyb_jsxx.jslsh = This.uf_getstring('退费交易流水号')
		astr_tzyb_jsxx.qrjslsh = This.uf_getstring('退费交易流水号')
		astr_tzyb_jsxx.jsrq  = This.uf_getdatetime('退费交易结算日期')
		of_get_ylfyzf(astr_tzyb_jsxx.str_yb_ylfyzf) 
		//		astr_tzyb_jsxx.smkzhye  = astr_tzyb_jsxx.str_yb_ylfyzf.qtzfs3
		of_get_jjfd(astr_tzyb_jsxx.str_tzyb_jjfd)

		of_update_jymx_tp(  ls_jsjylsh, as_jydd, ldt_jssj,  astr_tzyb_jsxx, as_error)

	END IF
	RETURN 1
ELSE
	IF IsNull(as_error) THEN as_error = 'NULL'
	RETURN -1
END IF
RETURN 1






