public function integer uf_jycx (string as_jylx, string as_jylsh, ref string as_jyjd, ref str_tzyb_jsxx astr_tzyb_jsxx, ref string as_error);//wangyi 已改
//1	是否有医保卡	string	1	是	1,0,2	0无卡，1有卡
//2	IC信息	string	300	否		
//3	现金支付方式	string	1	否		现金支付方式（1现金、2电子钱包、3银行借记卡，其它值默认为1）
//4	银行卡信息	string	50	否		暂时设定50个长度
//5	待查询用户交易类型号	string	2	是	30，31，32，36，37,40	可以查询的用户交易类型号有:30、31、32、36、37、40
//6	待查询的用户交易流水号	string	20	是		对应门诊序列号，住院序列号
//30门诊结算、31挂号退号/门诊退费、32住院登记、36住院结算、37住院退费、40取消住院登记。
This.uf_send_init('43')
This.uf_send_add('是否有医保卡','0')
This.uf_send_add('IC信息','')
This.uf_send_add('现金支付方式','1')
This.uf_send_add('银行卡信息','')
This.uf_send_add('待查询用户交易类型号', as_jylx)
IF as_jylx = '36' OR as_jylx = '37' THEN
	long ll_jsdh
   SELECT jsdh Into :ll_jsdh From bqxt.zy_brry Where zyhm = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = '获取jsdh失败：' + itran_sqlca.SQLErrText
		RETURN -1
	END IF
	IF ll_jsdh > 1 THEN
		as_jylsh = as_jylsh + '-'+String(ll_jsdh)
	END IF
END IF
This.uf_send_add('待查询的用户交易流水号', as_jylsh)
// 	返回参数(RetMsg)
//1	交易状态	integer	4	是		交易状态：0成功，小于0失败
//2	错误信息	string	100	否		 
//3	写医保卡结果	string	1	否		写医保卡结果：0表示不写或写卡成功，其他表示写卡错误信息
//4	扣银行卡结果	string	1	否		0表示不扣或扣成功
//5	更新后IC卡数据	string	300	否		预留
//6	用户交易是否成功	string	2	是		0成功，-1失败
//7	交易时间	datetime	20	否		 
//8	交易结算流水号	double	16	否		
//9	交易处于阶段	String	3	否		30，36三个交易分为0:已结算 1：已确认 其余没有确认交易的则默认为空
//10	该用户交易出口参数	composite	 			如果查询的交易为30，31，36，37返回的为计算结构体，请参考门诊预结算计算结果，其他交易返回为空
//11	基金分段信息结构体	composite	 			参照29号交易的基金分段信息
//12	费用汇总信息结构体	composite				参考36号交易的费用汇总信息结构体
//
IF This.uf_send( as_error) THEN
	IF This.uf_getstring("交易状态") <> '0' THEN
		as_error = This.uf_getstring("错误信息")
		RETURN -1
	ELSE
		IF This.uf_getstring("用户交易是否成功") <> '0' THEN
			as_error = "用户交易失败!"
			RETURN -1
		END IF
		astr_tzyb_jsxx.jsrq = This.uf_getdatetime( '交易时间')
		astr_tzyb_jsxx.jslsh = This.uf_getstring("交易结算流水号")
		IF as_jylx = '30' Or as_jylx = '31' Or as_jylx = '36' Or as_jylx = '37' THEN
//			of_get_ylfyzf(astr_tzyb_jsxx.str_yb_ylfyzf)
			IF as_jylx = '30' Or as_jylx = '36' THEN
				as_jyjd = This.uf_getstring("交易处于阶段") //0:已结算 1:已确认
				IF as_jyjd = '0' THEN
					as_jyjd = '0:已结算'
				ELSE
					as_jyjd = '1:已确认'
				END IF
			END IF
			of_get_ylfyzf(astr_tzyb_jsxx.str_yb_ylfyzf)
//			astr_tzyb_jsxx.smkzhye  = astr_tzyb_jsxx.str_yb_ylfyzf.qtzfs3
			of_get_jjfd(astr_tzyb_jsxx.str_tzyb_jjfd)
		END IF
		//12	费用汇总信息结构体
	END IF
ELSE
	RETURN -1
END IF
RETURN 1


end function

