//8	工伤身份验证结果	string	15	是		身份验证结果串长度蜠AT*
15位，部分位预留。医院可以对身份验证结果
//9	生育身份验证结果	string	15	是		身份验证结果串长度为15位，部分位预留。医院可以对身份验证结果

string ls_ylsfyzjg,ls_gssfyzjg,ls_sysfyzjg
ls_ylsfyzjg = This.uf_getstring('医疗身份验证结果')
ls_gssfyzjg = This.uf_getstring('工伤身份验证结果')
ls_sysfyzjg = This.uf_getstring('生育身份验证结果')

//医疗身份验证结果
//第1位：参保人员是否有效（0：正常参保 1：没参保或参保状态无效）  
//第2位：人员黑名单封锁（0正常，1冻结）
//第3位：住院冻结（0正常，1冻结）
//第4位：帐户冻结(保留)
//第5位：门诊待遇是否享受(0:享受,1不享受)
//第6位：规定病种待遇是否享受（0:享受,1不享受）
//第7位：住院待遇是否享受(0:享受,1不享受)
//第8位：家庭病床待遇是否享受(0:享受,1不享受)
//第9位：体检是否享受(0:享受,1不享受)
//其它位（10-15）：内部预留（返回0）
astr_tzyb_zhxx.str_tzyb_ylsfyz.cbrysfyx = integer(mid(ls_ylsfyzjg,1,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.ryhmdfs = integer(mid(ls_ylsfyzjg,2,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.zydj = integer(mid(ls_ylsfyzjg,3,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.zhdj = integer(mid(ls_ylsfyzjg,4,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.mzdysfxs = integer(mid(ls_ylsfyzjg,5,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.gdbzdysfxs = integer(mid(ls_ylsfyzjg,6,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.zydysfxs = integer(mid(ls_ylsfyzjg,7,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.jtbcdysfxs = integer(mid(ls_ylsfyzjg,8,1))
astr_tzyb_zhxx.str_tzyb_ylsfyz.tjsfxs = integer(mid(ls_ylsfyzjg,9,1))

//	工伤身份验证结果	
//第1位：参保人员是否有效（0：正常参盌AT*
 1：没参保或参保状态无效）  
//第2位：人员黑名单封锁（0正常，1冻结）
//第3位：住院冻结
//第4位：基金冻结（单位欠费）
//第5位：工伤待遇是否可以享受(0:已认定,1未认定)
//其它位（6-15）：内部预留（返回0）
astr_tzyb_zhxx.str_tzyb_gssfyz.cbrysfyx = integer(mid(ls_gssfyzjg,1,1))
astr_tzyb_zhxx.str_tzyb_gssfyz.ryhmdfs = integer(mid(ls_gssfyzjg,2,1))
astr_tzyb_zhxx.str_tzyb_gssfyz.zydj = integer(mid(ls_gssfyzjg,3,1))
astr_tzyb_zhxx.str_tzyb_gssfyz.jjdj = integer(mid(ls_gssfyzjg,4,1))
astr_tzyb_zhxx.str_tzyb_gssfyz.gsdysfkyxs = integer(mid(ls_gssfyzjg,5,1))

//	生育身份验证结果	
//第1位：参保人员是否有效（0：正常参保 1：没参保或参保状态无效）  
//第2位：人员黑名单封锁（0正常，1冻结）
//第3位：住院冻结
//第4位：基金冻结（单位欠费）
//第5位：生育待遇是否可以享受(0:享受,1不享受)
//其它位（6-15）：内部预留（返回0）
astr_tzyb_zhxx.str_tzyb_sysfyz.cbrysfyx = integer(mid(ls_sysfyzjg,1,1))
astr_tzyb_zhxx.str_tzyb_sysfyz.ryhmdfs = integer(mid(ls_sysfyzjg,2,1))
astr_tzyb_zhxx.str_tzyb_sysfyz.zydj = integer(mid(ls_sysfyzjg,3,1))
astr_tzyb_zhxx.str_tzyb_sysfyz.jjdj = integer(mid(ls_sysfyzjg,4,1))
astr_tzyb_zhxx.str_tzyb_sysfyz.sydysfkyxs = integer(mid(ls_sysfyzjg,5,1))
end subroutine

public function decimal of_get_zfbl79 (string as_cbrlb, string as_ypzllb, string as_zxxmbm, string as_ywlb, string as_yzmxxh, string as_dfybz, date adt_jfrq, string as_jylx, string as_jbbm, ref string as_error);//wangyi 已改
//====================================================================
// 事件: u_pyybjk_his.of_get_zfbl()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	string  	as_cbrlb 	
// 	value    	string  	as_ypzllb	
// 	value    	string  	as_zxxmbm	
// 	value    	string  	as_ywlb  	
// 	value    	string  	as_tsbbm 	
// 	value    	string  	as_dfybz 	
// 	value    	date	adt_jfrq 	
// 	reference	integer 	ai_sfdj  	
// 	reference	string  	as_error 	
//--------------------------------------------------------------------
// 返回:  decimal
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2013.04.17
//====================================================================
Dec{3} ldc_zfbl
//CBRLB, YPZLLB, XMZXLSH, YWLB, DFBZ
Long ll_ret = -100
IF as_jylx = 'PT' THEN
	SELECT ZFBL INTO :ldc_zfbl FROM jkxt.tzyb_ypzlzfbl WHERE YPZLBZ = :as_ypzllb AND	YPZLZXBM = :as_zxxmbm Using itran_sqlca;

	IF itran_sqlca.SQLCode <> 0 And itran_sqlca.SQLCode <> 100 THEN
		as_error = '获取自付比例和收费等级失败' + itran_sqlca.SQLErrText
		RETURN -1
	END IF
	ll_ret = itran_sqlca.SQLCode
END IF

String ls_jbbm = ''
//IF as_jylx = 'TSB' THEN //特殊病疾病编码
//	ls_jbbm = as_jbbm
//END IF

IF ll_ret = 100 Or as_jylx <> 'PT'  THEN
	This.uf_send_init('79')
	This.uf_send_add('是否有医保卡','0')
	This.uf_send_add('IC信息','')
	This.uf_send_add('现金支付方式','1')
	This.uf_send_add('银行卡信息','')
	This.uf_send_add('待遇类别',as_cbrlb)
	This.uf_send_add('业务类型',as_ywlb)//as_ywlb
	This.uf_send_add('疾病编码',as_jbbm) //7	疾病编码	string	20	否		如果是规定病报销则需要传入规定病编码，其余可为空
	this.uf_send_add_in_mxnr( '项目列表')
	This.uf_send_add_in('医嘱明细序号',as_yzmxxh,1)
	This.uf_send_add_in('药品诊疗类型',as_ypzllb,1)
	This.uf_send_add_in('医保中心编码',as_zxxmbm,1)
	This.uf_send_add_in('单复方标志',as_dfybz,1)
	This.uf_send_add_in('医嘱时间',String(adt_jfrq,'yyyymmdd'),1)
	IF uf_send(as_error) = True THEN
		//	1	交易状态	integer	4	是		交易状态：0成功，小于0失败
		//	2	错误信息	string	100	否		 
		//	3	写医保卡结果	string	1	否		写医保卡结果：0表示不写或写卡成功，其他表示写卡错误信息
		//	4	扣银行卡结果	string	1	否		0表示不扣或扣成功
		//	5	更新后IC卡数据	string	300	否		预留
		//	6	自付比例列表
		//	1)	医嘱明细序号
		// 2)	自付比列
		IF This.uf_getstring('交易状态') <> '0' THEN
			as_error = This.uf_getstring('错误信息')
			RETURN -1
		END IF
		ldc_zfbl = This.uf_getdecimal_in( '自付比列', 1)
	ELSE
		IF IsNull(as_error) THEN as_error = 'NULL'
		RETURN -1
	END IF
END IF
RETURN ldc_zfbl
end function

