public function integer uf_zydj (string as_knsj, long al_ksdm, long al_zyh, date ad_ryrq, string as_zyhm, string as_cwhm, string as_bahm, string as_ysbm, string as_ywlx, string as_rylx, string as_jbr, string as_zszh, ref string as_zydjjylsh, ref string as_error, ref transaction atr_trans, boolean ab_commit);//wangyi 20180920
String ls_ksbm = '0100',ls_ksmc = '刚入院未分配科室' ,ls_ysxm,ls_yszh//默认
String ls_zdmc = '',ls_ryzd = '',ls_zddm1,ls_zddm2,ls_zddm3,ls_klb,ls_zddms[],ls_zddmcs[]
Long ll_row,ll_tes,ll_jsdh
ls_klb = '1'

//准生证号
IF IsNull(as_zszh) THEN as_zszh = ''
//判断是否为生育，若为生育
IF as_rylx = '12' Or as_rylx = '15' THEN 
	as_ywlx = '52'
	as_rylx = '1'
END IF
IF as_ywlx = '52' THEN
	SELECT count(1) Into :ll_tes From bqxt.zy_brry_ye Where zyh = :al_zyh Using gtrans_temp_mssql;
	IF ll_tes <= 0 Or IsNull(ll_tes) THEN ll_tes = 0
ELSE
	ll_tes = 0
END IF

//用于计数，解决住院号码撤销登记不能用问题2017-6-13
SELECT jsdh Into :ll_jsdh From zy_brry Where zyh = :al_zyh Using atr_trans;
IF atr_trans.SQLCode  = 100 Or atr_trans.SQLCode = 0 THEN
	IF ll_jsdh >= 1 THEN
		ll_jsdh = ll_jsdh + 1
		as_zyhm = as_zyhm + "-" + String(ll_jsdh)
	END IF
END IF
IF IsNull(as_bahm) THEN as_bahm = ''
IF Pos(istr_yb_zhxx.knsj,'|') > 0 or left(as_knsj,6) = 'YBDZPZ' THEN
	ls_klb = '5'
	as_knsj = istr_yb_zhxx.knsj
ELSE
	ls_klb = '1'
END IF
