public function integer uf_mzdbz_tfcl (string as_knsj, string as_jslsh, string as_jbr, decimal adc_ylfyze, string as_jydd, datetime adt_jssj, ref str_tzyb_jsxx astr_tzyb_jsxx, ref str_yb_jsxx astr_yb_jsxx, ref string as_error);//====================================================================
// 事件: u_tzybjk_his.uf_mzdbz_tfcl()
//--------------------------------------------------------------------
// 描述:用于单边账退费
//--------------------------------------------------------------------
// 参数:
// 	value    	string       	as_knsj       	
// 	value    	string       	as_jslsh      	
// 	value    	string       	as_jbr        	
// 	value    	decimal      	adc_ylfyze    	
// 	value    	string       	as_jydd       	
// 	value    	datetime     	adt_jssj      	
// 	reference	str_tzyb_jsxx	astr_tzyb_jsxx	
// 	reference	str_yb_jsxx  	astr_yb_jsxx  	
// 	reference	string       	as_error      	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	zbq		日期: 2021.06.30
//====================================================================

//wangyi 已改
String ls_klb
Integer li_ret,li_ztbz

DateTime ldt_jssj_end


string ls_jssj
ls_jssj = String(RelativeDate ( Date(adt_jssj), -1 ),'yyyymmdd')
ldt_jssj_end = DateTime(RelativeDate(Date(adt_jssj),1),Time(23:59:59))
adt_jssj = DateTime(RelativeDate(Date(adt_jssj),-1))//,Time(adt_jssj)

select ztbz into:li_ztbz from jkxt.PYYB_JSMX  Where JSSJ >= :adt_jssj AND JSSJ <= :ldt_jssj_end And QRJYLSH = :as_jslsh ;
if li_ztbz<>99 then
	as_error='流水号：['+as_jslsh+']的交易不是单边账，不能发起单边账退费!'
	return -1
end if
gf_jsrz_tz("市本地.开始uf_mzdbz_tfcl()")  // 2021.05.13  CJN  24544  医保结算日志 市本地.开始uf_mzdbz_tfcl()
il_time_pre = CPU()
ls_klb = '1'
//IF Len(as_knsj) > 30 THEN
//	ls_klb = '2'
//ELSE
//	ls_klb = '0'
//END IF

IF uf_connect_sqlca_temp( ) < 0 THEN
	as_error = is_error
	RETURN -1
END IF
IF Pos(istr_yb_zhxx.knsj,'|') > 0 or left(as_knsj,6) = 'YBDZPZ' THEN
	ls_klb = '5'
	as_knsj = istr_yb_zhxx.knsj
ELSE
	ls_klb = '1'
