gf_jsrz_tz("市本地.uf_mzdbz_tfcl()内容构造结束，准备发送       历时："+String(CPU() - il_time_pre))  // 2021.05.13  CJN  24544  医保结算日志 市本地.uf_mzdbz_tfcl()内容构造结束，准备发送
il_time_send = CPU()
IF uf_send(as_error) = True THEN
	IF This.uf_getstring('交易状态') <> '0' THEN
		as_error = This.uf_getstring('错误信息')
		RETURN -1
	ELSE
		Integer li_cftf
		//6	是否为重复退费	int	1	否 0正常退费，1结算单在医保接口已经被退费过
		li_cftf = Integer(This.uf_getstring( '是否重复退费'))
		IF IsNull(li_cftf) THEN li_cftf = 0

		//不管是否为重复退费，都能让其继续退费
		IF li_cftf = 0 THEN
		ELSE
			as_error = '结算单在医保接口已经被退费过'
		END IF

		//7	退费交易流水号	string	20	是	
		//8	退稤AT*
	datetime	20	是	
		//9	计算结果信息	composite	 	否	
		//10	基金分段信息结构体	composite	 	否	

		astr_tzyb_jsxx.str_yb_grjbxx = This.istr_yb_zhxx.str_tzyb_grjbxx
		astr_tzyb_jsxx.jslsh = This.uf_getstring('退费交易流水号')
		astr_tzyb_jsxx.qrjslsh = This.uf_getstring('退费交易流水号')
		astr_tzyb_jsxx.jsrq  = This.uf_getdatetime('退费结算日期')
		of_get_ylfyzf(astr_tzyb_jsxx.str_yb_ylfyzf) 
		of_get_jjfd(astr_tzyb_jsxx.str_tzyb_jjfd) //astr_tzyb_jsxx.jsrq
		of_update_jymx_tpdbz(  as_jslsh, as_jydd, as_jbr,adt_jssj ,  astr_tzyb_jsxx, as_error)
	END IF
	gf_jsrz_tz("市本地.uf_mzdbz_tfcl()发送成功○                   历时："+String(CPU() - il_time_send))  // 2021.05.13  CJN  24544  医保结算日志 市本地.uf_mzdbz_tfcl()发送成功○
	RETURN 1
ELSE
	gf_jsrz_tz("市本地.uf_mzdbz_tfcl()发送失败×                   历时："+String(CPU() - il_time_send))  // 2021.05.13  CJN  24544  医保结算日志 市本地.uf_mzdbz_tfcl()发送失败×
	IF IsNull(as_error) THEN as_error = 'NULL'
	RETURN -1
END IF
RETURN 1

end function

public function integer of_update_jymx_ztbz (string as_jsjylsh, datetime adt_jssj, ref string as_error);//====================================================================
// 事件: u_tzybjk_his.of_update_jymx_ztbz()
//--------------------------------------------------------------------
// 描述:反交易又失败时对JKXT.PYYB_JSMX的ZTBZ，作如99处理
//--------------------------------------------------------------------
// 参数:
// 	value    	string       	as_jsjylsh  	    	
// 	value    	datetime     	adt_jssj    	
// 	reference	string       	as_error    	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	zbq		日期: 2021.06.30
//====================================================================

DateTime ldt_jssj_end,ldt_jssj
String ls_bzxx


IF uf_set_instance(as_error ) < 0 THEN
	RETURN -1
END IF

string ls_jssj
ls_jssj = String(RelativeDate ( Date(adt_jssj), -1 ),'yyyymmdd')
ldt_jssj_end = DateTime(RelativeDate(Date(adt_jssj),1),Time(23:59:59))
adt_jssj = DateTime(RelativeDate(Date(adt_jssj),-1))//,Time(adt_jssj)

gf_begin_transaction(itran_sqlca)

ls_bzxx = "reTraFail"
IF base_info.syscode = 5 Then
	ls_bzxx += "MZSF"
ELSEIF base_info.syscode = 10 Then
	ls_bzxx += "MZYS"
ELSEIF base_info.syscode = 32 Then
	ls_bzxx += "ZZCX"
ELSEIF base_info.syscode = 41 Then
	ls_bzxx += "FZHS"
ELSE
	ls_bzxx += String(base_info.syscode)
END IF
ldt_jssj= DateTime(RelativeDate(Date(adt_jssj),1))
ls_bzxx += string(ldt_jssj, 'yyyymmdd')+String(now(),'hhmm')+"|"


UPDATE JKXT.PYYB_JSMX  Set ZTBZ = 99, BZXX=BZXX||:ls_bzxx Where JSSJ >= :adt_jssj AND JSSJ <= :ldt_jssj_end And QRJYLSH = :as_jsjylsh  Using itran_sqlca ;

IF itran_sqlca.SQLCode = 0 THEN
	gf_commit_transaction(itran_sqlca)
	of_dbzrz("诊间单边账处理,流水号："+as_jsjylsh)//写日志
	RETURN 1
ELSE
	as_error = "JKXT.PYYB_JSMX的ZTBZ，99处理失败"+itran_sqlca.SQLErrText
	gf_rollback_transaction(itran_sqlca)
	RETURN -1
END IF


end function

