private function string of_numformat (decimal ad_datavalue, string as_datatype);//====================================================================
// 函数: u_ybjk.uf_numformat()
//--------------------------------------------------------------------
// 描述:	根据decimal数据格式类型，返回指定格式的字符串
//--------------------------------------------------------------------
// 参数:
// 	value	decimal	ad_datavalue	指定的数值
// 	value	string 	as_datatype 	指定的数值格式('da','db','dc','dd')				
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作誅AT*
:	XUMS		日期: 2011.8.3
//====================================================================
integer li_1 = 0
string ls_format
//'da','db','dc','dd','de','df','dg'
//,'dh','di','dj','dk','dl','dm','dn'
if isnull(ad_datavalue) then ad_datavalue = 0
choose case as_datatype
	case 'da','db','dc','df','dj','dk','dl','dn'//，2位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.00')
		else
			return string(ad_datavalue,'0.00')
		end if
	case 'de','dg'//3位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.000')
		else
			return string(ad_datavalue,'0.000')
		end if
	case 'dd','dh','di'//4位小数
		if ad_datavalue < 0 then
			return '-'+string(abs(ad_datavalue),'0.0000')
		else
			return string(ad_datavalue,'0.0000')
		end if
	case 'dm'
		if ad_datavalue < 0 then
			return '-'+string(integer(ad_datavalue))
		else
			return string(integer(ad_datavalue))
		end if
end choose


end function

private function string of_numformat (datetime adt_datavalue, string as_datatype);//====================================================================
// 函数: u_ybjk.uf_numformat()
//--------------------------------------------------------------------
// 描述:	根据datetime格式类型，返回指定格式的字符串
//--------------------------------------------------------------------
// 参数:
// 	value	decimal	ad_datavalue	指定的数值
// 	value	string 	as_datatype 	指定的数值格式('dta','dtb')				
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2009.06.17
//====================================================================


IF IsNull(adt_datavalue) THEN
	RETURN ''
END IF
CHOOSE CASE as_datatype
	CASE 'dta' //格式yyyymmdd hh24miss
		RETURN String(adt_datavalue,'yyyyMMddhhmmss')

	CASE 'dtb' //格式YYYYMMDD
		RETURN String(adt_datavalue,'YYYY-MM-DD')

	CASE ELSE
		RETURN ''
END CHOOSE



end function

