private function string of_get_errormessage (string as_returncode);//====================================================================
// 函数: u_ybjk.of_get_errormessage()
//--------------------------------------------------------------------
// 描述:	根据错误代码返回错误描述
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_returncode	返回码
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2009.06.17
//====================================================================

//返回值	定义
//0	操作成功
//-1	交易输入数据（函数输入）无效
//-2	网络故障
//-3	发送数据失败
//-4	接收数据失败
//-5	服务器返回数据无效
//-8	解析接收数据、组织返回数据失败
//-99	未知错误


CHOOSE CASE Upper(as_returncode)
	CASE '-1'
		RETURN '交易输入数据（函数输入）无效'
	CASE '-2'
		RETURN '网络故障'
	CASE '-3'
		RETURN '发送数据失败'
	CASE '-4'
		RETURN '接收数据失败'
	CASE '-5'
		RETURN '服务器返回数据无效'	
	CASE '-8'
		RETURN '解析接收数据、组织返回数据失败'
	CASE '-99'
		RETURN '未知错误'	
	case else
		return '代码：' + as_returncode
END CHOOSE

end function

public function integer uf_ykt_xzgzmy (ref string as_error);//下载工作密钥
//终端需于每天开展业务前下载工作密钥（工作密钥市民卡后台每天0点定时进行更新），并更新到相关设备中。
//InType（交易类型）：ZJ012

//序号	参考长度	数据项
//1	6	返回码
//2	20	柜员号
//3	32	工作密钥，16字符的pik+16字符的mak
//4	16	校验位
//5	14	服务端时间，yyyymmddhhmmss
string ls_fhm,ls_gyh,ls_gzmy,ls_jyw
datetime ldt_ffdsj

This.uf_send_init('ZJ012')
IF this.uf_send(as_error) = True THEN

	ls_fhm = This.of_getstring('返回码')
	ls_gyh = This.of_getstring('柜员号')
	ls_gzmy = This.of_getstring('工作密钥')
	ls_jyw = This.of_getstring('校验位')
	ldt_ffdsj = This.of_getdatetime('服务端时间')

	RETURN 1
ELSE
	IF IsNull(as_error) THEN as_error = 'NULL'
	RETURN -1
END IF
end function

