	//插入要发送的数据
	as_name = lower(as_name)
	li_row = ids_send.find("dataname = '"+as_name+"'",1,ids_send.rowcount())
	if li_row <= 0 then li_row = ids_send.insertrow(0)
	ids_send.object.dataname[li_row] = as_name
	ids_send.object.datavalue[li_row] = as_value
end if
end subroutine

public subroutine uf_send_init (string as_xxtlx);//====================================================================
// 函数: u_ybjk.uf_send_init()
//--------------------------------------------------------------------
// 描述:	指明消息体类型，并清空datastore里的数据
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_xxtlx	消息体类型
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2017-10-10
//====================================================================
String ls_ip
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\SMK_JY.dll' ) = False THEN
	is_init_errormessage = '健康一卡通的动态链接库(' + gu_api.uf_getcurrentappdirectory()+ '\SMK_JY.dll)不存在，请先安装'
	MessageBox('提示',is_init_errormessage)
	ib_init_success = False
	RETURN
END IF
//判断ini是否存在，判断ip是否匹配
IF FileExists(gu_api.uf_getcurrentappdirectory()+'\Treatment.ini' ) = False THEN
	is_init_errormessage = '健康一卡通的配置文件(' + gu_api.uf_getcurrentappdirectory()+ '下的Treatment.ini)不存在，请先安装'
	ib_init_success = False
	MessageBox('提示',is_init_errormessage)
	RETURN
ELSE
	ls_ip = ProfileString(gu_api.uf_getcurrentappdirectory()+"\Treatment.ini", "TransMachine_Config",  "addr", "")
	IF is_tzyktip <> ls_ip THEN
		is_init_errormessage = "数据库中健康一卡通前置机IP地址和Treatment.ini的addr不匹配，请检查"
		ib_init_success = False
		MessageBox('提示',is_init_errormessage)
		RETURN
	END IF
END IF
ib_init_success = True

is_xxtlx = Upper(as_xxtlx)
ids_send.Reset()
ids_structre.SetFilter( '')
ids_structre.Filter( )
end subroutine

