public function integer uf_yktcx_xxcx (str_tzykt_smkxx astr_tzykt_smkxx, ref string as_error);//市民卡信息查询
//InType（交易类型）：ZJ061
String ls_fhm,ls_gyh,ls_hjjd,ls_hjsq
Integer li_ksl

This.uf_send_init('ZJ061')
//This.uf_send_add('证件类型', as_zjlx)
//This.uf_send_add('证件号码', as_zjhm)
//This.uf_send_add('姓名', as_xm)
This.uf_send_add('证件类型',astr_tzykt_smkxx.zjlx)
This.uf_send_add('证件号翫AT* ',astr_tzykt_smkxx.zjhm) //330304198904123033
This.uf_send_add('姓名',astr_tzykt_smkxx.xm) //王毅

IF This.uf_send(as_error) = True THEN
	//序号	参考长度	数据项
	//1	6	返回码
	//2	20	柜员号
	//3	32	户籍所在乡镇（街道）
	//4	32	户籍所在村（社区）
	//5	2	卡数量
	//	...	
	//6	20	市民卡卡号
	//7	3	卡类型（100全功能卡；252 健康卡）
	//8	1	卡状态（1正常；2挂失；8预挂失；9注销）
	//9	8	卡余额
	//		重复6-9
	ls_fhm = This.of_getstring('返回码')
	ls_gyh = This.of_getstring('柜员号')
	ls_hjjd = This.of_getstring('户籍所在乡镇（街道）')
	ls_hjsq = This.of_getstring('户籍所在村（社区）')
	li_ksl = This.of_getdecimal('卡数量')

	astr_tzykt_smkxx.kh_old = ''
	Integer li_row
	IF li_ksl > 0 THEN
		FOR li_row = 1 To li_ksl
			ids_yktqd.Object.yktkh[li_row] = This.of_getstring_in('市民卡卡号',li_row)
			ids_yktqd.Object.klx[li_row] = This.of_getstring_in('卡类型',li_row)
			ids_yktqd.Object.kzt[li_row] = This.of_getdecimal_in('卡状态',li_row)
			ids_yktqd.Object.kye[li_row] = This.of_getdecimal_in('卡余额',li_row)
			IF ids_yktqd.Object.klx[li_row] = '252' And ids_yktqd.Object.kzt[li_row] <> 9 THEN
				astr_tzykt_smkxx.kh_old = ids_yktqd.Object.yktkh[li_row]
			END IF
		NEXT
	END IF

	RETURN 1
ELSE
	IF IsNull(as_error) THEN as_error = 'NULL'
	RETURN -1
END IF


end function

