public function datetime uf_getdatetime (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdatetime()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date或datetime类型)，返回接收到的值datetime
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  datetime
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

Int li_find
String ls_datatype,ls_datavalue
DateTime ldt_datavalue
li_find = ids_receive.Find("dataname = '"+Lower(as_name)+"'", 1, ids_receive.RowCount())
IF li_find > 0 THEN
	ls_datatype = ids_receive.Object.DataType[li_find]
	CHOOSE CASE ls_datatype
	//		case 'dt' //日期格式为YYYY-MM-DD HH:MM:SS
	//			ls_datavalue = trim(ids_receive.object.datavalue[li_find])
	//			return datetime(date(left(ls_datavalue,10)),time(right(ls_datavalue,8)))
		CASE 'dta' //日期格式为YYYYMMDD/HHNNSS/
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			IF Not IsNumber ( Mid(ls_datavalue,5,1) ) THEN
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,6,2) + "-" + Mid(ls_datavalue,9,2) + " " + Mid(ls_datavalue,12,2) + ":" + Mid(ls_datavalue,15,2)+ ":" + Mid(ls_datavalue,18,2)
			ELSE
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2) + " " + Mid(ls_datavalue,10,2) + ":" + Mid(ls_datavalue,12,2)+ ":" + Mid(ls_datavalue,14,2)
			END IF
			//			ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,6,2) + "-" + mid(ls_datavalue,9,2) + " " + mid(ls_datavalue,12,2) + ":" + mid(ls_datavalue,15,2)+ ":" + mid(ls_datavalue,18,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)),Time(Right(ls_datavalue,8)))
		CASE 'dtb' //日期格式为YYYYMMDD
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)))


		CASE ELSE
			gf_sblogmsg('数据类型不匹配,该函数只返回datetime类型('+as_name+')')
			SetNull(ls_datavalue)
			SetNull(ldt_datavalue)
			RETURN ldt_datavalue
	END CHOOSE
ELSE
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	SetNull(ldt_datavalue)
	RETURN ldt_datavalue
END IF



end function

