public function date uf_getdate_in (string as_name, long al_row);//====================================================================
// 函数: u_ybjk.uf_getdate()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date类型)，返回接收到的值date
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  date
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2011.7.20
//====================================================================

//日期格式为YYYY-MM-DD
Int li_find
String ls_datatype,ls_datavalue
li_find = ids_receive_in.Find("Upper(dataname) = '"+Upper (as_name)+"' and datarow=" +String(al_row)+" and datamxnr='"+is_mxnr+"'", 1, ids_receive_in.RowCount())

IF li_find > 0 THEN
	ls_datatype = ids_receive_in.Object.DataType[li_find]
	IF ls_datatype = 'dtb' THEN
		ls_datavalue = Trim(ids_receive_in.Object.datavalue[li_find])
		IF Len(ls_datavalue) = 8 THEN
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)

END IF
	ELSE
		gf_sblogmsg('数据类型不匹配,该函数只返回date类型('+as_name+')')
		SetNull(ls_datavalue)
	END IF
ELSE
	gf_sblogmsg('字段名不存在('+as_name+')' + "行:" +String(al_row))
	SetNull(ls_datavalue)
END IF

RETURN Date(Left(ls_datavalue,10))

end function

public function decimal uf_getdecimal_in (string as_name, long al_row);//====================================================================
// 函数: u_ybjk.uf_getdecimal()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为decimal)，返回接受到的值decimal
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  decimal
//--------------------------------------------------------------------
// 作者:	sz		日期: 2009.06.17
//====================================================================

int li_find
string ls_datatype,ls_datavalue
li_find = ids_receive_in.find("Upper(dataname) = '"+Upper (as_name)+"' and datarow=" +string(al_row)+" and datamxnr='"+is_mxnr+"'", 1, ids_receive_in.rowcount())

if li_find > 0 then
	ls_datatype = ids_receive_in.object.datatype[li_find]
	if ls_datatype >= 'da' and ls_datatype < 'dz' then
		ls_datavalue = ids_receive_in.object.datavalue[li_find]
	else
		gf_sblogmsg('数据类型不匹配,该函数只返回decimal类型('+as_name+')' +ls_datatype )
		setnull(ls_datavalue)
	end if
else
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	setnull(ls_datavalue)
end if
return dec(ls_datavalue)
end function

