public function string of_get_dzdmsb (string as_table, string as_tjlxh);//====================================================================
// 事件: u_zhyl_his.of_get_dzdmsb()
//--------------------------------------------------------------------
// 描述: 获取 GY_DMZD_ZD表 中的对照结果
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_table	
// 	value	string	as_tjlxh	
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	CJN 		日期: 2022.01.17    28271    获取 GY_DMZD_ZD表 中的对照结果
//====================================================================

IF Upper(as_table) = 'GY_DMZD' THEN
	RETURN ''
END IF

Long ll_find
IF Upper(as_table) = 'GY_JBBM' Or Upper(as_table) = 'GY_JBBM_SYD' THEN //wangyi 20200319 诊断单独拿出来获取
	ll_find = ids_dmzd_dz_jb.Find("Upper(tname)='" + Upper(as_table) + "' and Upper(tjlxh)='" + Upper(as_tjlxh) + "'",1,999999)
	IF ll_find > 0 THEN
		RETURN ids_dmzd_dz_jb.Object.dmsb_dz[ll_find]
	ELSE
		RETURN '无'
	END IF
END IF

ll_find = ids_dmzd_dz.Find("Upper(tname)='" + Upper(as_table) + "' and Upper(tjlxh)='" + Upper(as_tjlxh) + "'",1,999999)
IF ll_find > 0 THEN
	RETURN ids_dmzd_dz.Object.dmsb_dz[ll_find]
ELSE
	RETURN '无'
END IF

end function

public function string of_get_dzdmsbmc (string as_table, string as_tjlxh);//====================================================================
// 事件: u_zhyl_his.of_get_dzdmsbmc()
//--------------------------------------------------------------------
// 描述: 获取医保名称
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_table	
// 	value	string	as_tjlxh	
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.17    28271  获取医保名称
//====================================================================

IF Upper(as_table) = 'GY_DMZD' THEN
	RETURN ''
END IF

Long ll_find,ll_jlxh
ll_find = ids_dmzd_dz.Find("Upper(tname)='" + Upper(as_table) + "' and Upper(tjlxh)='" + Upper(as_tjlxh) + "'",1,999999)
IF ll_find > 0 THEN
	IF ids_dmzd_dz.Object.dmmc[ll_find] > '' THEN
		RETURN ids_dmzd_dz.Object.dmmc[ll_find]
	ELSE
		String ls_dmmc
		CHOOSE CASE Upper(as_table)
			CASE 'GY_KSDM'
				ll_jlxh = long(as_tjlxh)
				SELECT KSMC Into :ls_dmmc From GY_KSDM Where KSDM = :ll_jlxh Using itran_sqlca;
			CASE 'MZ_KS'
				SELECT mc Into :ls_dmmc From mz_ks Where ksbm = :as_tjlxh Using itran_sqlca;
			CASE 'YK_YPSX'
				SELECT SXMC Into :ls_dmmc From YPXT.YK_YPSX Where YPSX = :as_tjlxh Using itran_sqlca;
		END CHOOSE
		ids_dmzd_dz.Object.tname[ll_find] = Upper(as_table)
		ids_dmzd_dz.Object.tjlxh[ll_find] = as_tjlxh
		ids_dmzd_dz.Object.dmmc[ll_find] = ls_dmmc
		RETURN ls_dmmc
	END IF
ELSE
	CHOOSE CASE Upper(as_table)
		CASE 'GY_KSDM'
			ll_jlxh = long(as_tjlxh)
			SELECT KSMC Into :ls_dmmc From GY_KSDM Where KSDM = :ll_jlxh Using itran_sqlca;
		CASE 'MZ_KS'
			SELECT mc Into :ls_dmmc From mz_ks Where ksbm = :as_tjlxh Using itran_sqlca;
		CASE 'YK_YPSX'
			SELECT SXMC Into :ls_dmmc From YPXT.YK_YPSX Where YPSX = :as_tjlxh Using itran_sqlca;
		CASE else
			ls_dmmc = 'NULL'
	END CHOOSE
	If ISNULL(ls_dmmc) THEN ls_dmmc = 'NULL'
	RETURN ls_dmmc
END IF

end function

