public function integer of_get_ybgrbh (string as_knsj, ref string as_ybgrbh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_get_ybgrbh()
//--------------------------------------------------------------------
// 描述: 获取本地医保人员编号
//--------------------------------------------------------------------
// 睤AT*
:
// 	value    	string	as_knsj  	
// 	reference	String	as_ybgrbh	
// 	reference	string	as_error 	      	
//--------------------------------------------------------------------
// 返回:  integer
//        -1-失败；1-成功
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.19    28271  获取本地医保人员编号
//====================================================================

String ls_ybgrbh

ls_ybgrbh = as_ybgrbh
IF isnull(ls_ybgrbh) Then ls_ybgrbh=''
IF Trim(ls_ybgrbh)>'' Then return 1

IF isnull(as_knsj) or Trim(as_knsj)='' Then
	as_error = "卡号为空！"
	goto Error
END IF

Select GRBH into :ls_ybgrbh From JKXT.YB_BRJBXX where YB_BRJBXX.KNSJ=:as_knsj Using itran_sqlca;
IF itran_sqlca.sqlcode<>0 Then
	as_error = "获取本地医保人员编号失败：("+String(itran_sqlca.sqlcode)+")"+itran_sqlca.sqlErrText
	goto Error
END IF

as_ybgrbh = ls_ybgrbh
return 1

Error:
as_error = "获取本地医保病人基本信息失败：" + as_error
return -1
end function

public function integer of_get_xzlx (ref string as_xzlx, string as_yllb, string as_rylb, string as_gwybz, string as_error);//====================================================================
// 事件: u_zhyl_his.of_get_xzlx()
//--------------------------------------------------------------------
// 描述: 获取险种类型
//--------------------------------------------------------------------
// 参数:
// 	reference	String	as_xzlx
// 	value    	string	as_yllb 	 医疗类别：21-普通住院，22-外伤住院，23-转外诊治住院，24-急诊转住院，25-异地住院，26-单病种住院，28-日间手术，52-生育住院，92-其他住院，......
// 	value    	string	as_rylb 	 人员类别：11-在职，1101-职工在职，1102-公务员在职，......  12-退休，1202-职工退休，1202-公务员退休，......  13-离休，......  14-居民（未成年），......  15-居民（成年），......
// 	value    	string	as_gwybz  公务员标志：0-否，1-是，......
// 	reference	String	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN 		日期: 2022.01.20    28271  获取险种类型
//====================================================================

// 险种类型：
// 	310	职工基本医疗保险
// 	31003	医疗保险个人账户（用人单位）
// 	312	农民工住院医疗	
// 	320	公务员医疗补助	
//		321	公务员医疗补助（市直统发）	
//		323	公务员医疗补助（市直非统发）
//		330	大额医疗费用补助
//		331	二次补助	
//		340	离休人员医疗保障	
//		350	一至六级残废军人医疗补助
//		370	企业补充医疗保险
//		360	老红军医疗保障
//		380	新型农村合作医疗
//		390	城乡居民基本医疗保险
//		39901	劳模医疗保障
//		39902	补充百分之十医疗
