//		39905	二乙医疗保险
//		39906	意外伤害医疗保险
//		391	城镇居民基本医疗保险
//		392	城乡居民大病医疗保险
//		399	其他特殊人员医疗保障
//		410	长期照护保险
//		510	生育保险
//		520	公务员生育

IF as_yllb='52' Then  // 生育住院
	IF as_gwybz>'0' or as_rylb='1102' or as_rylb='1202' or as_rylb='1114' Then
		as_xzlx = '520'
	ELSE
		as_xzlx = '510'
	END IF
ELSE
	IF as_gwybz>'0' or as_rylb='1102' or as_rylb='1202' or as_rylb='1114' Then
		as_xzlx = '320'
	ELSE
		as_xzlx = '310'
	END IF
END IF

IF isnull(as_xzlx) or Trim(as_xzlx)='' Then 
	as_xzlx = '310'
END IF

return 1

end function

