public function integer of_update_tsjl (string as_brbm, decimal ad_zyh, integer ai_jscs, string as_ywly, string as_ywlsh, decimal adc_tsje, string as_ybywh, string as_mxzdh, ref string as_error);//====================================================================
// 事件: u_ybjk_new_his.of_insert_tsjl()
//--------------------------------------------------------------------
// 描述:插入干部保健虳AT*

//--------------------------------------------------------------------
// 参数:
// 	value    	string 	as_brbm 	
// 	value    	decimal	ad_zyh  	
// 	value    	integer	ai_jscs 	
// 	value    	string 	as_ywly 	
// 	value    	decimal	adc_tsje	
// 	value    	string 	as_ywlsh	
// 	value    	string 	as_ybywh	
// 	reference	string 	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2017.03.21
//====================================================================
DateTime ldt_kssj
ldt_kssj = DateTime(RelativeDate(Date(idt_sysdatetime),-1))
IF IsNull(as_brbm) THEN
	UPDATE JKXT.JS_TSJL SET ztbz = 1,YBYWH = :as_ybywh,tszje = :adc_tsje
		WHERE TSSJ >= :ldt_kssj AND ZYH = :ad_zyh AND JSCS = :ai_jscs AND YWLY = :as_ywly AND YWLSH = :as_ywlsh and mxzdh = :as_mxzdh
		Using itran_sqlca ;
ELSE
	UPDATE JKXT.JS_TSJL SET ztbz = 1,YBYWH = :as_ybywh,tszje = :adc_tsje
		WHERE TSSJ >= :ldt_kssj AND BRBM = :as_brbm AND YWLY = :as_ywly AND YWLSH = :as_ywlsh and mxzdh = :as_mxzdh
		Using itran_sqlca ;
END IF

IF itran_sqlca.SQLCode = 0 THEN
	IF ad_zyh > 0 THEN
		UPDATE JKXT.JS_TSMX Set ztbz = 1,JSCS = :ai_jscs,TSYWH = :as_ywlsh Where ZYH = :ad_zyh And JSCS = 0  And MXZDH = :as_mxzdh And ztbz = 0 Using itran_sqlca ;
	ELSE
		UPDATE JKXT.JS_TSMX Set ztbz = 1 Where TSYWH = :as_ywlsh And MXZDH = :as_mxzdh And ztbz = 0 Using itran_sqlca ;
	END IF
	IF itran_sqlca.SQLCode = 0 THEN
		RETURN 1
	ELSE
		as_error = '更新干部保健托收明细失败：' + itran_sqlca.SQLErrText
		RETURN -1
	END IF
ELSE
	as_error = '更新干部保健托收记录失败：' + itran_sqlca.SQLErrText
	RETURN -1
END IF
RETURN 1






end function

public function integer of_update_tsjl_tp (datetime adt_kssj, datetime adt_jssj, string as_ybywh, decimal adc_tsje, string as_tjylsh, string as_jsfl, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_update_tsjl_tp()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	datetime	adt_kssj 	
// 	value    	datetime	adt_jssj 	
// 	value    	string  	as_ybywh 	
// 	value    	decimal 	adc_tsje 	
// 	value    	string  	as_tjylsh	
// 	value    	string  	as_jsfl  	
// 	reference	string  	as_error 	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2022.01.22
//====================================================================

UPDATE JKXT.JS_TSJL  Set ZTBZ = 2 Where  TSSJ >= :adt_kssj And TSSJ <= :adt_jssj And YBYWH = :as_ybywh And ZTBZ = 1   Using itran_sqlca ;
if as_jsfl = 'YF' THEN
	INSERT INTO JKXT.JS_TSJL
				 (  TSSJ,     BRBM,   ZYH,   JSCS,  YWLY, mxzdh, TSZJE,    YWLSH,   YBYWH,   ZTBZ ,GBBZ,JMBL,JSFL)
		SELECT sysdate,BRBM,  ZYH,  JSCS,  YWLY, '-' || mxzdh, :adc_tsje, YWLSH,  :as_tjylsh, 3,GBBZ,JMBL,JSFL
		FROM JKXT.JS_TSJL
		WHERE  TSSJ >= :adt_kssj AND TSSJ <= :adt_jssj AND YBYWH = :as_ybywh AND ZTBZ IN (1,2)
		Using itran_sqlca ;
ELSE
	INSERT INTO JKXT.JS_TSJL
				 (  TSSJ,     BRBM,   ZYH,   JSCS,  YWLY, mxzdh, TSZJE,    YWLSH,   YBYWH,   ZTBZ ,GBBZ,JMBL,JSFL)
		SELECT sysdate,BRBM,  ZYH,  JSCS,  YWLY, mxzdh, :adc_tsje, YWLSH,  :as_tjylsh, 3,GBBZ,JMBL,JSFL
		FROM JKXT.JS_TSJL
		WHERE  TSSJ >= :adt_kssj AND TSSJ <= :adt_jssj AND YBYWH = :as_ybywh AND ZTBZ IN (1,2)
		Using itran_sqlca ;
END IF
IF itran_sqlca.SQLCode = 0 And itran_sqlca.SQLNRows >= 1 THEN
	//	UPDATE JKXT.JS_TSMX Set ZTBZ = 2 Where  TSSJ >= :adt_kssj And TSSJ <= :adt_jssj And YBYWH = :as_ybywh And ZTBZ = 1   Using itran_sqlca ;
	gf_commit_transaction(itran_sqlca)
	RETURN 1
ELSE
	as_error = itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
	gf_rollback_transaction(itran_sqlca)
	RETURN -1
END IF


RETURN 1
end function

