	END IF
END IF


// 可冲正的交易包括：【2102A】药店结算、【2103】药店结算撤销、【2207A】门诊结算、【2208】门诊结算撤销、【2304A】住院紻AT*
2305】住院结算撤销、【2401】入院办理
//String ls_jylxs = ",2102A,2103,2207A,2208,2304A,2305,2401,2102,2207,2304,"

IF IsNull(as_jylx) Or Trim(as_jylx) = '' THEN
	as_error = '需要冲正的【交易编号】为空！'
	GOTO Error
END IF
IF IsNull(as_grbh) Or Trim(as_grbh) = '' THEN
	as_error = '冲正交易所需的【人员编号】为空！'
	GOTO Error
END IF
IF IsNull(as_jyjslsh) Or Trim(as_jyjslsh) = '' THEN
	as_error = '冲正交易所需的【原发送方报文ID/医疗机构结算ID】为空！'
	GOTO Error
END IF
//IF Pos(ls_jylxs, ","+as_jylx+",") <= 0 THEN
//	as_error = "冲正的交易编号有误：" + as_jylx
//	GOTO Error
//END IF

This.uf_send_init( '2601')

istr_jytsrx.opter = ls_czybm // 修改Header中的"opter"，以确保操作员和其签到流水号一致
IF Trim(istr_yb_grjbxx_zhyl.cbdxzqhdm) > ""  THEN
	istr_jytsrx.insuplc_admdvs = istr_yb_grjbxx_zhyl.cbdxzqhdm // 修改Header中的"insuplc_admdvs"，以确保参保地一致
END IF

This.uf_send_add('psn_no', as_grbh) // 人员编号
This.uf_send_add('omsgid', as_jyjslsh) // 原发送方报文ID
This.uf_send_add('oinfno', as_jylx) // 原交易编号

// 发送报文
IF Not uf_send(Ref as_error, '') = True THEN
	GOTO Error
END IF
// 成功后回写HIS
IF IsNull(adt_jssj) Or Date(adt_jssj) < Date(2000,1,1) THEN
	adt_jssj  = DateTime(Date(gf_server_date()))
END IF
IF as_jylx = '2401' THEN
	gf_begin_transaction(itran_sqlca)
	UPDATE JKXT.ZHYB_ZYDJMX Set ZTBZ = -1 Where JYLSH = :as_jyjslsh Using itran_sqlca;
	IF itran_sqlca.SQLCode = 0 THEN
		gf_commit_transaction(itran_sqlca)
	ELSE
		gf_rollBack_transaction(itran_sqlca)
	END IF
ELSE
	This.of_jsmx_zf(as_jylx, adt_jssj, as_jyjslsh, Ref as_error)

	String ls_ywlsh = '0000',ls_ywlx,ls_fph
	Long ll_zyh
	IF as_jylx = '2207A' Or as_jylx = '2207' THEN
		//作废交易同时撤销明细和挂号
		SELECT ywlx,ywlsh,fph Into :ls_ywlx,:ls_ywlsh,: ls_fph From JKXT.zhyb_jsmx Where jssj >= :adt_jssj - 3 And jssj <= :adt_jssj + 3 And JZID = :ls_jzid And ZTBZ = -2 Using itran_sqlca;
		IF ls_ywlsh > '' THEN
			IF ls_ywlx <> 'GH' Or IsNull(ls_ywlx) THEN ls_ywlx = ''
			IF ii_zymz = 1 THEN
				SELECT zyh Into :ll_zyh From zy_brry,JKXT.zhyb_ghxx Where zy_brry.zyhm = zhyb_ghxx.brbm And JZID = :ls_jzid And ZTBZ = 1 Using itran_sqlca;
				This.uf_zymz_delfymx( ll_zyh, '0000', as_error)
			ELSE
				This.uf_mz_mxcx( ls_jzid, ls_ywlsh, as_grbh, as_error)
				This.uf_mz_ghcx( as_grbh, ls_jzid, ls_ywlx +ls_ywlsh , adt_jssj,as_error)
			END IF
		ELSE
			IF ii_zymz = 1 THEN
				SELECT zyh Into :ll_zyh From zy_brry,JKXT.zhyb_ghxx Where zy_brry.zyhm = zhyb_ghxx.brbm And JZID = :ls_jzid And ZTBZ = 1 Using itran_sqlca;
				This.uf_zymz_delfymx( ll_zyh, '0000', as_error)
			ELSE
				This.uf_mz_mxcx( ls_jzid, '0000', as_grbh, as_error)
			END IF
		END IF
	ELSEIF as_jylx = '2304' THEN
		SELECT ZYH Into :ll_zyh From JKXT.zhyb_jsmx Where jssj >= :adt_jssj - 3 And jssj <= :adt_jssj + 3 And JZID = :ls_jzid And ZTBZ = -2 and jylsh = :as_jyjslsh order by jylsh desc Using itran_sqlca;
		if ll_zyh >= 0 then uf_zy_crycx( 2, ll_zyh, ls_tmp)
	END IF
END IF
RETURN 1

Error:
as_error = "[2601-冲正交易]出错：" + as_error
RETURN -1

end function

public function integer of_get_expcontent (ref string as_return, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_get_expcontent()
//--------------------------------------------------------------------
// 描述: 获取 exp_content-字段扩展
//--------------------------------------------------------------------
// 参数:
// 	reference	string	as_return	
// 	reference	string	as_error 	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.22    28271  获取 exp_content-字段扩展
//====================================================================

//HW 门诊外伤
sailJson ljson_expContent
ljson_expContent = Create sailJson

// 非省异地
IF istr_yb_grjbxx_zhyl.sydbz = 0 THEN

	//是否启用门诊外伤 HW 2023/09/05
	IF ii_mzws = 1 THEN
		// 门诊外伤标志为2表示签了无第三方责任书
		IF as_return = '2' THEN
			ljson_expContent.setAttribute("insutype", istr_yb_grjbxx_zhyl.insutype)
			ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
			ljson_expContent.setAttribute("rel_ttp_flag", "0") //涉及第三方责任标志
		ELSEIF as_return = '1' THEN //门诊外伤标志为1表示未签了无第三方责任书
			ljson_expContent.setAttribute("insutype", istr_yb_grjbxx_zhyl.insutype)
			ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
			ljson_expContent.setAttribute("rel_ttp_flag", "1") //未签无第三方责任书
		ELSEIF  as_return = '22' THEN
			ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
			ljson_expContent.setAttribute("rel_ttp_flag", "0") //涉及第三方责任标志
		END IF
		as_return = ljson_expContent.getformatjson("")

		IF IsValid(ljson_expContent) THEN Destroy(ljson_expContent)
	ELSE
		as_return = ""
	END IF

	RETURN 1
END IF

// 省异地
// 2023/09/05 注释
//sailJson ljson_expContent
//ljson_expContent = Create SailJson

ljson_expContent.setAttribute("psn_cert_type", istr_yb_grjbxx_zhyl.psn_cert_type) // 人员证件类型
ljson_expContent.setAttribute("certno", istr_yb_grjbxx_zhyl.certno) // 证件号码
ljson_expContent.setAttribute("psn_name", istr_yb_grjbxx_zhyl.brxm) // 人员姓名
ljson_expContent.setAttribute("psn_type", istr_yb_grjbxx_zhyl.psn_type) // 人员类别
ljson_expContent.setAttribute("insutype", istr_yb_grjbxx_zhyl.insutype) // 险种类型
ljson_expContent.setAttribute("cvlserv_flag", istr_yb_grjbxx_zhyl.cvlserv_flag) // 公务员标志
ljson_expContent.setAttribute("card_sn", istr_yb_grjbxx_zhyl.shbzksbm ) // 卡识别码

// 门诊外伤标志为2表示签了无第三方责任书
IF as_return = '2' THEN
	ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
	ljson_expContent.setAttribute("rel_ttp_flag", "0") //涉及第三方责任标志
ELSEIF as_return = '1' THEN //门诊外伤标志为1表示未签了无第三方责任书
	ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
	ljson_expContent.setAttribute("rel_ttp_flag", "1") //未签无第三方责任书
ELSEIF as_return = '22' THEN //住院外伤
	ljson_expContent.setAttribute("trum_flag", "1") // 外伤标志
	ljson_expContent.setAttribute("rel_ttp_flag", "0") //涉及第三方责任标志
	as_return = ""
END IF

as_return = ljson_expContent.getformatjson("")

IF IsValid(ljson_expContent) THEN Destroy(ljson_expContent)

IF IsNull(as_return) Or Trim(as_return) = "" THEN
	as_error = "省异地病人扩展字段内容不能为空！"
	RETURN -1
END IF

RETURN 1

end function

public function integer of_update_ghxx (integer ai_gxlx, str_zhyl_ghxx astr_zhyl_ghxx, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_update_ghxx()
//--------------------------------------------------------------------
// 描述:更新挂号信息
//--------------------------------------------------------------------
// 参数:
// 	value    	string       	as_jsjylsh    	
// 	value    	str_zhyb_ghxx	astr_zhyb_ghxx	
// 	reference	string       	as_error      	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2022.01.21
//====================================================================

DateTime ldt_curr,ldt_end
ldt_curr = astr_zhyl_ghxx.kssj
IF uf_set_instance(as_error ) < 0 THEN
	RETURN -1
END IF

gf_begin_transaction(itran_sqlca)
IF ai_gxlx = 0 THEN
	ldt_curr = of_relativetime('HOUR',ldt_curr,2)
	UPDATE JKXT.ZHYB_GHXX  SET ZTBZ = 1,JZID = :astr_zhyl_ghxx.JZID
		Where JYSJ  >= :ldt_curr And JYLSH = :astr_zhyl_ghxx.JYLSH Using  itran_sqlca ;
	IF itran_sqlca.SQLCode = 0 And itran_sqlca.SQLNRows = 1 THEN
		gf_commit_transaction(itran_sqlca)
		RETURN 0
	ELSE
		as_error = itran_sqlca.SQLErrText + " 更新列:" + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF
ELSEIF ai_gxlx = 1 THEN
	ldt_end = DateTime(RelativeDate(Date(ldt_curr),3),Time(ldt_curr)) //of_relativetime('HOUR',ldt_curr,-36)
	ldt_curr = DateTime(RelativeDate(Date(ldt_curr),-3),Time(ldt_curr))
	if ii_zymz = 1 then
		UPDATE JKXT.ZHYB_GHXX  SET ZTBZ = -1,bzxx = '作废' || :is_jylsh,ZFSJ = SYSDATE
			Where KSSJ  >= :ldt_curr And KSSJ <= :ldt_end And JZID = :astr_zhyl_ghxx.JZID And ZTBZ = 1 Using  itran_sqlca ;
	else
		UPDATE JKXT.ZHYB_GHXX  SET ZTBZ = -1,bzxx = '作废' || :is_jylsh,ZFSJ = SYSDATE
			Where JYSJ  >= :ldt_curr And JYSJ <= :ldt_end And JZID = :astr_zhyl_ghxx.JZID And ZTBZ = 1 Using  itran_sqlca ;
	end if
	IF itran_sqlca.SQLCode = 0 THEN
		gf_commit_transaction(itran_sqlca)
		RETURN 0
	ELSE
		as_error = itran_sqlca.SQLErrText + " 作废更新列:" + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF
END IF


end function

public function integer of_get_expcontent (string as_ywlx, string as_jzid, string as_brbm, long al_zyh, ref string as_return, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_get_expcontent()
//--------------------------------------------------------------------
// 描述: 获取 exp_content-字段扩展（数据库中已有数据时使用）
//--------------------------------------------------------------------
// 参数:
// 	value    	string	as_ywlx  	
// 	value    	String	as_jzid  	
// 	value    	string	as_brbm  	
// 	value    	long  	al_zyh   	
// 	reference	string	as_return	
// 	reference	string	as_error 	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.22    28271  获取 exp_content-字段扩展（数据库中已有数据时使用）
//====================================================================

Integer li_sydyz
String ls_zjlx, ls_sfzh, ls_brxm, ls_lyrylb, ls_xzlx, ls_gwybz, ls_jzpzbh,ls_shbzksbm

IF as_ywlx='ZY' Then
	Select     SYDBZ,     ZJLX,     ZJHM,     BRXM,     YLRYLB,     XZLX,     GWYBZ,     JZPZBH
	  into :li_sydyz, :ls_zjlx, :ls_sfzh, :ls_brxm, :ls_lyrylb, :ls_xzlx, :ls_gwybz, :ls_jzpzbh
	  From JKXT.ZHYB_ZYDJMX
	 Where JZID=:as_jzid and ZYH=:al_zyh
	 Using itran_sqlca;
	IF itran_sqlca.sqlcode<>0 Then
		as_error = "获取住院登记明细失败：("+String(itran_sqlca.sqlcode)+")" + itran_sqlca.sqlErrText
	END IF
	select zhbz into :ls_shbzksbm from zy_brry where  ZYH=:al_zyh  Using itran_sqlca; 
	istr_yb_grjbxx_zhyl.sydbz = li_sydyz
	istr_yb_grjbxx_zhyl.psn_cert_type = ls_zjlx
	istr_yb_grjbxx_zhyl.certno = ls_sfzh
	istr_yb_grjbxx_zhyl.brxm = ls_brxm
	istr_yb_grjbxx_zhyl.psn_type = ls_lyrylb
	istr_yb_grjbxx_zhyl.insutype = ls_xzlx
	istr_yb_grjbxx_zhyl.cvlserv_flag = ls_gwybz
	IF isnull(istr_yb_grjbxx_zhyl.shbzkkh) or Trim(istr_yb_grjbxx_zhyl.shbzkkh)="" Then
		istr_yb_grjbxx_zhyl.shbzkkh = ls_jzpzbh
	END IF
	if isnull(istr_yb_grjbxx_zhyl.shbzksbm) or Trim(istr_yb_grjbxx_zhyl.shbzksbm)=""  then
		istr_yb_grjbxx_zhyl.shbzksbm = ls_shbzksbm
	end if
ELSEIF as_ywlx='MZ' Then

ELSE
	as_error = "业务类型有误：" + as_ywlx
	goto Error
END IF

IF This.of_get_expcontent( ref as_return, ref as_error)<0 Then
	goto Error
END IF

return 1

Error:
IF as_ywlx='MZ' Then 
	as_error = "门诊省异地病人 " + as_error
ELSEIF as_ywlx='ZY' Then
	as_error = "住院省异地病人 " + as_error
END IF
as_error = "获取扩展字段失败：" + as_error
return -1
end function

