public function integer uf_ryddbacx (string as_dysbmxlsh, string as_grbh, string as_bzxx, ref string as_error, boolean ab_returnerror);//====================================================================
// 事件: u_zhyl_his.uf_ryddbacx()
//--------------------------------------------------------------------
// 描述: 人员定点备案撤销
//--------------------------------------------------------------------
// 参数:
// 	value    	string 	as_dysbmxlsh  	
// 	value    	string 	as_grbh       	
// 	value    	string 	as_bzxx       	
// 	reference	string 	as_error      	
// 	value    	boolean	ab_returnerror		 	
//--------------------------------------------------------------------
// 返籇AT*
:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.19    28271  人员定点备案撤销
//====================================================================

IF isnull(as_dysbmxlsh) or Trim(as_dysbmxlsh)="" Then
	as_error = "待遇申报明细流水号为空！"
	goto Error
END IF

//签到同时获取交易周期号
IF This.uf_czy_qrqc(Today(), base_info.UserID, 1, ref as_error)<0 THEN
	goto Error
END IF

//使用临时事务
IF uf_set_instance(as_error) < 0 THEN
	RETURN -1
END IF

IF isnull(as_bzxx) Then as_bzxx=""
IF Lenw(as_bzxx)>500 Then
	as_error = "撤销原因超过500字，请简略内容！(当前"+String(Lenw(as_bzxx))+"字)"
	goto Error
END IF

this.uf_send_init('2506')
this.uf_send_add('trt_dcla_detl_sn', as_dysbmxlsh)  // 待遇申报明细流水号
this.uf_send_add('psn_no', as_grbh)						 // 人员编号
this.uf_send_add('memo', as_bzxx)					    // 备注


// 发送报文
IF NOT This.uf_send(ref as_error, "") Then
	goto Error
END IF


// 成功后回写HIS
// 若 2505-人员定点备案 医保单边成功，调用该函数进行冲正交易时，只需医保端成功即可
IF ab_returnError=False Then
	return 1
END IF

IF Trim(as_bzxx)>"" Then
	as_bzxx = "||撤销原因：" + as_bzxx
END IF

// 1.优先更新状态，若事务出错需要返回错误
gf_begin_transaction(itran_sqlca)
Update JKXT.ZHYB_RYDDBAMX Set ZTBZ = -1 Where DYSBLSH = :as_dysbmxlsh Using itran_sqlca;
IF itran_sqlca.sqlcode=0 Then
	gf_commit_transaction(itran_sqlca)
ELSE
	as_error = "【医保端】人员备案撤销成功，但更新人员备案明细表失败，请联系信息科处理。错误信息：["+String(itran_sqlca.sqlCode)+"]"+itran_sqlca.SQLErrText
	gf_rollBack_transaction(itran_sqlca)
	goto Error
END IF

// 2.再更新备注信息，若事务出错则无视
Update JKXT.ZHYB_RYDDBAMX Set BZXX=BZXX||:as_bzxx Where DYSBLSH=:as_dysbmxlsh Using itran_sqlca;
IF itran_sqlca.sqlcode=0 Then
	gf_commit_transaction(itran_sqlca)
ELSE
	gf_rollBack_transaction(itran_sqlca)
END IF



return 1

Error:
as_error = "[2506-人员定点备案撤销] " + as_error
return -1

end function

