public function integer uf_zydj (ref string as_knsj, long al_ksdm, long al_zyh, datetime adt_ryrq, string as_zyhm, string as_cwhm, string as_bahm, string as_ysbm, string as_rylx, ref string as_jzbh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.uf_zydj()
//--------------------------------------------------------------------
// 描述: 病区住院登记最终入口
//--------------------------------------------------------------------
// 参数:
// 	reference	string  	as_knsj 	
// 	value    	long    	al_ksdm 	
// 	value    	long    	al_zyh  	
// 	value    	datetime	adt_ryrq	
// 	value    	string  	as_zyhm 	
// 	value    	string  	as_cwhm 	
// 	value    	string  	as_bahm 	
// 	value    	string  	as_ysbm 	
// 	reference	string  	as_jzbh 	
// 	reference	string  	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.22    28271  病区住院登记最终入緿AT*

//====================================================================

//根据adt_ryrq是否为空来判别是否取住院数据
IF IsValid(gtrans_temp_mssql) = True THEN
	IF gtrans_temp_mssql.DBHandle( ) > 0 THEN GOTO Process_GetID // 数据库已连接
ELSE
	gtrans_temp_mssql = Create Transaction
	//gtrans_temp_ora = itrans_bq 
	gtrans_temp_mssql.DBMS       = sqlca.DBMS
	gtrans_temp_mssql.ServerName = sqlca.ServerName
	gtrans_temp_mssql.Database   = sqlca.Database
	gtrans_temp_mssql.LogID      = sqlca.LogID
	gtrans_temp_mssql.LogPass    = sqlca.LogPass
	gtrans_temp_mssql.UserID     = sqlca.UserID
	gtrans_temp_mssql.DBPass     = sqlca.DBPass
	gtrans_temp_mssql.DBParm     = sqlca.DBParm
	gtrans_temp_mssql.Lock 		 = sqlca.Lock
END IF

CONNECT Using gtrans_temp_mssql ;

IF gtrans_temp_mssql.SQLCode <> 0 THEN
	as_error = '创建gtrans_temp_mssql事务失败:' + gtrans_temp_mssql.SQLErrText
	RETURN -1
END IF
Process_GetID:

RETURN uf_zydj(ref as_knsj, al_ksdm, al_zyh, adt_Ryrq, as_zyhm, as_cwhm, as_bahm, as_ysbm, as_rylx, ref as_JZbh, ref as_error, ref gtrans_temp_mssql, True)


end function

