public function integer uf_mz_mxcx (string jzid, string sfpch, string grbh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.uf_mz_mxcx()
//--------------------------------------------------------------------
// 描述:【2205】门诊费用明细信息撤销
//--------------------------------------------------------------------
// 参数:
// 	value    	string	jzid  	
// 	value    	string	sfpch	
// 	value    	string	grbh    	
// 	reference	string	as_error 	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2022.01.26
//====================================================================
DateTime ldt_now
String ls_czybm
ldt_now = gf_server_date()
IF base_info.syscode = 5 THEN
	ls_czybm = base_info.UserID
	IF This.uf_czy_qrqc( Date(ldt_now), base_info.UserID , 1, as_error) < 0 THEN
		RETURN -1
	END IF
ELSE
	ls_czybm = is_mzzz
	IF This.uf_czy_qrqc( Date(ldt_now),is_mzzz , 1, as_error) < 0 THEN
		RETURN -1
	END IF
END IF
String ls_expcontent
IF This.of_get_expcontent( ls_expcontent, as_error) < 0 THEN
	RETURN -1
END IF
This.uf_send_init( '2205')
istr_jytsrx.insuplc_admdvs = istr_yb_grjbxx_zhyl.cbdxzqhdm
istr_jytsrx.opter = ls_czybm
This.uf_send_add( 'mdtrt_id', jzid) //mdtrt_id	就诊ID	字符型	30		Y	
This.uf_send_add( 'chrg_bchno', sfpch) //chrg_bchno	收费批次号	字符型	30		Y	传入"0000"删除所有未结算明细
This.uf_send_add( 'psn_no', grbh) //psn_no	人员编号	字符型	30		Y	
This.uf_send_add( 'exp_content', ls_expcontent) //exp_content	字段扩展	字符型	4000	
IF Not uf_send(as_error,'') THEN
	RETURN -1
ELSE
	//如果撤销成功，更新对应表
END IF
RETURN 1

end function

