//更新数据状态为上传成功
//====================================================================

//参数定义
long ll_count,ll_index
boolean lb_save_success
string ls_return,ls_error,ls_temp

//将状态转为成功
ll_count = ads_zfbrjyxxsc.rowcount()
For ll_index = 1 to ll_count
	ads_zfbrjyxxsc.object.ZTBZ[ll_index] = 1
NEXT
ll_count = ads_zfbrjyxxsczd.rowcount()
For ll_index = 1 to ll_count
	ads_zfbrjyxxsczd.object.ZTBZ[ll_index] = 1
NEXT
ll_count = ads_zfbrjyxxscmx.rowcount()
For ll_index = 1 to ll_count
	ads_zfbrjyxxscmx.object.ZTBZ[ll_index] = 1
NEXT

