gf_begin_transaction( this.itran_sqlca )
lb_save_success = true
IF lb_save_success Then
	IF ads_zfbrjyxxsc.Update() = 1 THEN
	ELSE
		gf_rollback_transaction( this.itran_sqlca )
		as_error = '保存出错:zfbrjyxxsc' + ads_zfbrjyxxsc.is_error
		lb_save_success = false
	END IF
END IF
