	IF ads_zfbrjyxxsczd.Update() = 1 THEN
	ELSE
		gf_rollback_transaction( this.itran_sqlca )
		as_error = '保存出错:zfbrjyxxsczd' + ads_zfbrjyxxsczd.is_error
		lb_save_success = false
	END IF
END IF
IF lb_save_success Then
	IF ads_zfbrjyxxscmx.Update() = 1 THEN
	ELSE
		gf_rollback_transaction( this.itran_sqlca )
		as_error = '保存出错:zfbrjyxxscmx' + ads_zfbrjyxxscmx.is_error
		lb_save_success = false
	END IF
END IF

//结束
IF lb_save_success THEN 
	gf_commit_transaction( this.itran_sqlca )
	return 1
