public function integer of_insert_tsjl (string as_brbm, decimal ad_zyh, integer ai_jscs, string as_ywly, decimal adc_tsje, string as_ywlsh, string as_mxzdh, string as_gbdxbz, ref string as_error);//====================================================================
// 事件: u_ybjk_new_his.of_insert_tsjl()
//--------------------------------------------------------------------
// 描述:插入干部保健托收记录
//--------------------------------------------------------------------
// 参数:
// 	value    	string 	as_brbm 	
// 	value    	decimal	ad_zyh  	
// 	value    	integer	ai_jscs 	
// 	value    	string 	as_ywly 	
// 	value    	decimal	adc_tsje	
// 	value    	string 	as_ywlsh	
// 	value    	string 	as_ybywh	
// 	reference	string 	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
