public subroutine of_judge_dcsc1tfy (ref boolean ab_dcsc1t);//====================================================================
// 事件: u_zhyl_his.of_judge_dcsc1tfy()
//--------------------------------------------------------------------
// 描述: 用于判断本次明细上传是否包含多条只能单次1条的费用
//--------------------------------------------------------------------
// 参数:
// 	reference	boolean	ab_dcsc1t	
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.03.06    28271  用于判断本次明细上传是否包含多条只能单次1条的费用
//====================================================================

Long ll_row, ll_rowCount
String ls_fyxh
Long ll_count = 0
ll_rowCount = ids_zyfymx.RowCount()

IF ll_rowCount <= 0 THEN RETURN

FOR ll_row = ll_rowCount To 1 Step -1

	IF ids_zyfymx.Object.yplx[ll_row] = 0 THEN // 费用
		ls_fyxh = String(ids_zyfymx.Object.fyxh[ll_row])

		IF Pos(is_DCSC1TFYXH, ','+ls_fyxh+',') > 0 THEN
			ll_count++
			IF ll_count > 1 THEN
				ab_dcsc1t = False
				ids_zyfymx.DeleteRow(ll_row)
			END IF
		END IF
	END IF

NEXT

IF ll_count = 1 And ids_zyfymx.Object.fysl[1] > 0 THEN
	ab_dcsc1t = False
END IF



end subroutine

