public function integer of_jsmx_zf (string as_jylx, datetime adt_jysj, string as_jylsh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_jsmx_zf()
//--------------------------------------------------------------------
// 描述: 冲正结算类交易后，对本地结算明细表进行作废
//--------------------------------------------------------------------
// 参数:
// 	value    	string  	as_jylx 	 【2102A】药店结算、【2103】药店结算撤销、【2207A】门诊结算、【2208】门诊结算撤销、【2304A】住院结算、【2305】住院结算撤销、【2401】入院办理
// 	value    	datetime	adt_jysj	
// 	value    	string  	as_jylsh	
// 	reference	string  	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.01.21    28271  冲正结算类交易后，对本地结算明细表进行作废
//====================================================================

IF uf_set_instance(as_error ) < 0 THEN
	RETURN -1
END IF

String ls_jzid
DateTime ldt_juf_set_instance
of_constructor
ids_dmzd_jk
u_datastore
itran_sqlca
setworktrans
 SELECT JLXH,DMLB,DMSB,DMMC,DMJC FROM XTGL.GY_DMZD_JK WHERE JKLX = 'ZHYL'
createfromsql
创建'发药方式'对象失败( settransobject ids_dmzd_dz ssj ldt_jssj = gf_relativedatetime('HOUR',adt_jysj,24)

gf_begin_transaction(itran_sqlca)

IF as_jylx = '2207A' Or as_jylx = '2207' Or as_jylx = '2304A' Or as_jylx = '2304' THEN // 冲正 结算类 交易
	UPDATE JKXT.ZHYB_JSMX Set ZTBZ = -2 Where JSSJ >= :ldt_jssj And JYLSH = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = "【医保端】冲正交易成功，但作废本地结算明细失败：" + itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF

	UPDATE JKXT.ZHYB_JSMX_KZ Set ZTBZ = -2 Where JYLSH = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = "【医保端】冲正交易成功，但作废本地结算明细基金分项失败：" + itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF
	gf_commit_transaction(itran_sqlca)


	// 住院结算回滚时，需要把已结算的明细回滚到未结算的状态
	IF as_jylx = '2304A' Or as_jylx = '2304' THEN
		dec{0} ldc_zyh
		integer li_jscs
		SELECT JZID,ZYH,JSCS Into :ls_jzid,:ldc_zyh,:li_jscs From JKXT.ZHYB_JSMX Where JSSJ >= :ldt_jssj And JYLSH = :as_jylsh Using itran_sqlca;
		UPDATE JKXT.ZHYB_FYMXSC Set ZTBZ = ZTBZ-1 Where zyh =:ldc_zyh and  JZID = :ls_jzid And ZTBZ In(1,10) Using itran_sqlca;
		IF ii_zyqy_qy > 0 THEN
			UPDATE JKXT.ZHYB_FYMXSC_ZY Set ZTBZ = ZTBZ-1 Where zyh =:ldc_zyh and  JZID = :ls_jzid And ZTBZ In(1,10) Using itran_sqlca;		
		END IF
		IF itran_sqlca.SQLCode <> 0 Or itran_sqlca.SQLNRows <= 0 THEN
			as_error = "【医保端】冲正交易成功，但更新费用明细上传状态失败：["+String(itran_sqlca.SQLCode)+"]" + itran_sqlca.SQLErrText +  " 更新列：" + String(itran_sqlca.SQLNRows)
			gf_rollback_transaction(itran_sqlca)
		ELSE
			UPDATE JKXT.JS_TSMX SET ZTBZ = 0,JSCS = 0 WHERE ZYH =:ldc_zyh AND JSCS = :li_jscs AND MXZDH = :ls_jzid AND ZTBZ = 1 Using itran_sqlca;
			gf_commit_transaction(itran_sqlca)
		END IF
	END IF

	RETURN 1

ELSEIF as_jylx = '2208' Or as_jylx = '2305' THEN // 冲正 撤销类 交易（不知道怎么处理HIS，暂时先处理成和结算类冲正一样的效果）
	UPDATE JKXT.ZHYB_JSMX Set ZTBZ = -2 Where JSSJ >= :ldt_jssj And JYLSH = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = "【医保端】冲正交易成功，但作废本地结算明细失败：" + itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF

	UPDATE JKXT.ZHYB_JSMX_KZ Set ZTBZ = -2 Where JYLSH = :as_jylsh Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = "【医保端】冲正交易成功，但作废本地结算明细基金分项失败：" + itran_sqlca.SQLErrText +  '更新列:' + String(itran_sqlca.SQLNRows)
		gf_rollback_transaction(itran_sqlca)
		RETURN -1
	END IF
	gf_commit_transaction(itran_sqlca)

	RETURN 1
END IF
RETURN 1


end function

