		UPDATE JKXT.ZHYB_FYMXSC Set ZTBZ=-1 Where ZYH=:al_zyh and ZTBZ in(0,9,-2) and YWLSH=:as_fymxlsh Using itran_sqlca;
	END IF
	IF itran_sqlca.SQLCode<>0 THEN
		as_error = "【医保端】费用明细撤销成功，但作废费用明细上传表数据失败：("+String(itran_sqlca.SQLCode)+")" + itran_sqlca.SQLErrText
		gf_rollback_transaction(itran_sqlca)
	//	goto Error
	END IF

	UPDATE JKXT.JS_TSMX Set ZTBZ = -1 Where ZYH = :al_zyh And ZTBZ = 0 And JSCS = 0 and YWLSH=:as_fymxlsh Using itran_sqlca;
	UPDATE BQXT.ZY_FYMX SET ZFJE = ZJJE - NVL(YHJE,0) ,ZFBL = 1 WHERE  ZYH = :al_zyh And JSCS = 0 and YWLSH=:as_fymxlsh Using itran_sqlca;
END IF
gf_commit_transaction(itran_sqlca)
RETURN 1


Error:
as_error = "[2205-住院费用明细按门诊撤销]出错：" + as_error
return -1
end function

