public function integer of_handle_zyfymx_sfjl_sc (long al_zyh, string as_jzid, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_handle_zyfymx_sfjl_sc()
//--------------------------------------------------------------------
// 描述:ids_zysfjl_sc表检索后，初步对表数据进行处理，以获得有可退数量的业务流水号
//--------------------------------------------------------------------
// 参数:
// 	value    	long  	al_zyh  	
// 	value    	string	as_jzid 	
// 	reference	string	as_error	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	CJN		日期: 2022.02.27    28271    ids_zysfjl_sc表检索后，初步对表数据进行处理，以获得有可退数量的业务流水号
//====================================================================

IF IsValid(ids_zysfjl_sc) = False THEN
	ids_zysfjl_sc = Create u_datastore
	ids_zysfjl_sc.setworktrans(itran_sqlca)
	IF ii_zyqy_qy = 1 or ii_zyqy_br = 1 THEN
		ids_zysfjl_sc.DataObject = 'd_zhyb_zyfymx_sfjl_zyhz'
	ELSE
		ids_zysfjl_sc.DataObject = 'd_zhyb_zyfymx_sfjl_hz'
	END IF
ELSE
	IF (ii_zyqy_qy = 1 or ii_zyqy_br = 1) And ids_zysfjl_sc.DataObject <> 'd_zhyb_zyfymx_sfjl_zyhz' THEN
		ids_zysfjl_sc.DataObject = 'd_zhyb_zyfymx_sfjl_zyhz'
	ELSEIF ii_zyqy_br = 0 And ids_zysfjl_sc.DataObject <> 'd_zhyb_zyfymx_sfjl_hz' THEN
		ids_zysfjl_sc.DataObject = 'd_zhyb_zyfymx_sfjl_hz'
	END IF
END IF
ids_zysfjl_sc.SetTransObject(itran_sqlca)
IF ids_zysfjl_sc.Retrieve(al_zyh, as_jzid) < 0 THEN
	as_error = "检索已上传收费记录失败：" + ids_zysfjl_sc.is_error
	RETURN -1
END IF

Long ll_row, ll_rowCount, ll_find
Dec ldc_sl
String ls_yxmywlsh, ls_find

ll_rowCount = ids_zysfjl_sc.RowCount()
IF ll_rowCount <= 0 THEN RETURN 1

FOR ll_row = ll_rowCount To 1 Step -1

	ldc_sl = ids_zysfjl_sc.Object.SL[ll_row]

	IF ldc_sl >= 0 THEN CONTINUE;

	// 根据退费记录，去寻找原业务流水号，并将数量减掉
	ls_yxmywlsh = ids_zysfjl_sc.Object.YXMYWLSH[ll_row]
	ll_find = ids_zysfjl_sc.Find(" (YWLSH='"+ls_yxmywlsh+"') ", 1, ll_rowCount)
	IF ll_find > 0 THEN
		ids_zysfjl_sc.Object.SL[ll_find] = ids_zysfjl_sc.Object.SL[ll_find] + ldc_sl // ldc_sl为负数，故用+
	END IF

	// 剔除本条退费明细
	ids_zysfjl_sc.DeleteRow(ll_row)

NEXT
RETURN 1


end function

