public function date uf_getdate_original (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdate_original()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date类型)，返回接收到的值date
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  date
//--------------------------------------------------------------------
// 作者:	XUMS		日期: 2009.06.17
//====================================================================

//日期格式为YYYY-MM-DD
int li_find
string ls_datatype,ls_datavalue
li_find = ids_send_old.find("dataname = '"+as_name+"'", 1, ids_send_old.rowcount())
if li_find > 0 then
	ls_datatype = ids_send_old.object.data
type[li_find]
	if ls_datatype = 'd' then
		ls_datavalue = trim(ids_send_old.object.datavalue[li_find])
	else
		gf_sblogmsg('数据类型不匹配,该函数只返回date类型('+as_name+')')
		setnull(ls_datavalue)
	end if
else
	gf_sblogmsg('字段名不存在('+as_name+')')
	setnull(ls_datavalue)
end if

return date(left(ls_datavalue,10))
end function

public function datetime uf_getdatetime (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdatetime()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为date或datetime类型)，返回接收到的值datetime
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  datetime
//--------------------------------------------------------------------

//====================================================================

Int li_find
String ls_datatype,ls_datavalue
DateTime ldt_datavalue
li_find = ids_receive.Find("dataname = '"+as_name+"'", 1, ids_receive.RowCount())
IF li_find > 0 THEN
	ls_datatype = ids_receive.Object.DataType[li_find]
	CHOOSE CASE ls_datatype
	//		case 'dt' //日期格式为YYYY-MM-DD HH:MM:SS
	//			ls_datavalue = trim(ids_receive.object.datavalue[li_find])
	//			return datetime(date(left(ls_datavalue,10)),time(right(ls_datavalue,8)))
		CASE 'dta' //日期格式为YYYYMMDDHHMMSS--YYYYMMDDHH24MISS
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			IF Not IsNumber ( Mid(ls_datavalue,5,1) ) THEN
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,6,2) + "-" + Mid(ls_datavalue,9,2) + " " + Mid(ls_datavalue,12,2) + ":" + Mid(ls_datavalue,15,2)+ ":" + Mid(ls_datavalue,18,2)
			ELSE
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2) + " " + Mid(ls_datavalue,9,2) + ":" + Mid(ls_datavalue,11,2)+ ":" + Mid(ls_datavalue,13,2)
			END IF
			//			ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,6,2) + "-" + mid(ls_datavalue,9,2) + " " + mid(ls_datavalue,12,2) + ":" + mid(ls_datavalue,15,2)+ ":" + mid(ls_datavalue,18,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)),Time(Right(ls_datavalue,8)))
		CASE 'dtb' //日期格式为YYYYMMDD
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)))		

		CASE ELSE
			gf_sblogmsg('数据类型不匹配,该函数只返回datetime类型('+as_name+')')
			SetNull(ls_datavalue)
			SetNull(ldt_datavalue)
			RETURN ldt_datavalue
	END CHOOSE
ELSE
	gf_sblogmsg('消息体类型:'+is_xxtlx+'返回的数据,字段名不存在('+as_name+')')
	SetNull(ldt_datavalue)
	RETURN ldt_datavalue
END IF



end function

public function datetime uf_getdatetime_original (string as_name);//====================================================================
// 函数: u_ybjk.uf_getdatetime_original()
//--------------------------------------------------------------------
// 描述:	根据指定的字段名称(该字段必须为datetime类型)，返回发送时的值datetime
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_name	
//--------------------------------------------------------------------
// 返回:  datetime
//--------------------------------------------------------------------

//====================================================================


int li_find
string ls_datatype,ls_datavalue
datetime ldt_datavalue
li_find = ids_send_old.find("dataname = '"+as_name+"'", 1, ids_send_old.rowcount())
if li_find > 0 then
	ls_datatype = ids_send_old.object.datatype[li_find]
	choose case ls_datatype
//		case 'dt' //日期格式为YYYY-MM-DD HH:MM:SS
//			ls_datavalue = trim(ids_send_old.object.datavalue[li_find])
//			return datetime(date(left(ls_datavalue,10)),time(right(ls_datavalue,8)))
		case 'dt'//日期格式为YYYYMMDD/HHNNSS/
			ls_datavalue = trim(ids_send_old.object.datavalue[li_find])
			ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,5,2) + "-" + mid(ls_datavalue,7,2) + " " + mid(ls_datavalue,10,2) + ":" + mid(ls_datavalue,12,2)+ ":" + mid(ls_datavalue,14,2)
			return datetime(date(left(ls_datavalue,10)),time(right(ls_datavalue,8)))
		CASE 'dta' //日期格式为YYYYMMDDHHNNSS
			ls_datavalue = trim(ids_send_old.object.datavalue[li_find])
			IF not IsNumber ( Mid(ls_datavalue,5,1) ) THEN
				ls_datavalue = mid(ls_datavalue,1,4) + "-" + mid(ls_datavalue,6,2) + "-" + mid(ls_datavalue,9,2) + " " + mid(ls_datavalue,12,2) + ":" + mid(ls_datavalue,15,2)+ ":" + mid(ls_datavalue,18,2)
			ELSE				
				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2) + " " + Mid(ls_datavalue,9,2) + ":" + Mid(ls_datavalue,11,2)+ ":" + Mid(ls_datavalue,13,2)
//				ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2) + " " + Mid(ls_datavalue,10,2) + ":" + Mid(ls_datavalue,12,2)+ ":" + Mid(ls_datavalue,14,2)
			END IF
			RETURN DateTime(Date(Left(ls_datavalue,10)),Time(Right(ls_datavalue,8)))
		CASE 'dtb' //日期格式为YYYYMMDD
			ls_datavalue = Trim(ids_receive.Object.datavalue[li_find])
			ls_datavalue = Mid(ls_datavalue,1,4) + "-" + Mid(ls_datavalue,5,2) + "-" + Mid(ls_datavalue,7,2)
			RETURN DateTime(Date(Left(ls_datavalue,10)))		
		case else
			gf_sblogmsg('数据类型不匹配,该函数只返回datetime类型('+as_name+')')
			setnull(ldt_datavalue)
			return ldt_datavalue
	end choose
else
	gf_sblogmsg('字段名不存在('+as_name+')')
	setnull(ldt_datavalue)
	return ldt_datavalue
end if

end function

public function decimal uf_getdecimal (string as_name);//====================================================================
