public function integer of_get_gjbm (string as_bmlx, string as_ybbm, ref string as_gjbm);
IF uf_connect_sqlca_temp( ) < 0 THEN
	as_gjbm = is_error
	RETURN -1
END IF
String ls_gjm = '',ls_gjm_temp,ls_ygxm,ls_sfzh,ls_dzgh
ls_gjm_temp = as_gjbm
IF as_bmlx = 'YSBM' THEN
	IF IsValid(ids_ygdm) = False THEN
		//IF of_get_ygxm(as_ybbm,ls_ygxm,ls_sfzh,True,as_gjbm) < 0 THEN
		//	as_gjbm = '获取医师信息失败：' + as_gjbm
		//	RETURN -1
		//END IF
	END IF
	Long ll_find,ll_find_dz
	ll_find = ids_ygdm.Find("ygdm = '"+as_ybbm+"'",1,99999)
	IF ll_find > 0 THEN
		ls_dzgh =  ids_ygdm.Object.dzgh[ll_find]
		IF ls_dzgh > '' THEN //如果有对照取对照，没有就取本身
			ll_find_dz = ids_ygdm.Find("ygdm = '"+ls_dzgh+"'",1,99999)
			IF ll_find_dz >  0 THEN
				ll_find = ll_find_dz
				as_ybbm = ls_dzgh
			END IF
		END IF
		ls_gjm = Trim(ids_ygdm.Object.gjybdm[ll_find])
		IF IsNull(ls_gjm) THEN ls_gjm = ''
	ELSE
		//IF of_get_ygxm(as_ybbm,ls_ygxm,ls_sfzh,True,as_gjbm) < 0 THEN
		//	as_gjbm = '获取医师信息失败：' + as_gjbm
			//RETURN -1
		//ELSE
			ll_find = ids_ygdm.Find("ygdm = '"+as_ybbm+"'",1,99999)
			IF ll_find <= 0 THEN
				as_gjbm = '获取医师信息失败2：' + as_ybbm
				RETURN -1
			else
				ls_dzgh =  ids_ygdm.Object.dzgh[ll_find]
				IF ls_dzgh > '' THEN //如果有对照取对照，没有就取本身
					ll_find_dz = ids_ygdm.Find("ygdm = '"+ls_dzgh+"'",1,99999)
					IF ll_find_dz >  0 THEN
						ll_find = ll_find_dz
						as_ybbm = ls_dzgh
					END IF
				END IF
			END IF
	//	END IF
		ls_gjm = ''
	END IF

	IF ls_gjm = '' Or IsNull(ls_gjm) THEN
		SELECT gjybdm Into :ls_gjm From xtgl.gy_ygdm_kz Where ygdm = :as_ybbm Using itran_sqlca;
		IF itran_sqlca.SQLCode <> 0 And itran_sqlca.SQLCode <> 100 THEN
			as_gjbm = as_ybbm + '，获取国家码失败：' + itran_sqlca.SQLErrText
			RETURN -1
		ELSE
			IF IsNull(ls_gjm) Or ls_gjm = '' THEN
				ls_gjm = 'NULL'
				as_gjbm = ''
				//					as_gjbm = as_ybbm + '，未维护对应的国家码！'
				//					RETURN 0
			ELSE
				as_gjbm = Trim(ls_gjm)
			END IF
		END IF
		ids_ygdm.Object.gjybdm[ll_find] = Trim(ls_gjm)
	ELSE
