public function long of_get_jbxx (integer ai_yplx, long al_ypxh, long al_ypcd, string as_ywlx, datetime adt_jfrq, ref string as_xmzxbh_ts, ref integer ai_tsdz, ref string as_error);//====================================================================
// 事件: u_zhyl_his.of_get_jbxx()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	value    	integer 	ai_yplx     	
