String ls_sql
IF Not IsValid(ids_typk) THEN
	ids_typk = Create U_datastore
	ids_typk.setworktrans( itran_sqlca)
	ls_sql = " SELECT YK_TYPK.YPXH,'' as GJYBBM,YK_TYPK.YPJL,YK_TYPK.JLDW,YK_TYPK.YFGG,YK_TYPK.BFGG,"+&
		" YK_TYPK.BFDW,YK_TYPK.YFDW,YK_TYPK.ZJPB,YK_TYPK.TYPE,YK_TYPK.ZXDW,YK_TYPK.KZYP,0 AS LBTSDZ,0 AS YPCD,0 AS TSDZ,0 as wgyp,'' as YLMLBM,'' as YLJGMLBM,'' AS MEMO,'' AS MLLB,'' AS SYFYBZ," +&
		" to_date('1900-01-01','yyyy/mm/dd') AS MLKSRQ, to_date('2099-12-31','yyyy/mm/dd') AS MLJSRQ, '' as SFLB, '' as ybmlmc, '' as ybmldj, '' as YPMC "+&
		" FROM YPXT.YK_TYPK "
	IF ids_typk.createfromsql(ls_sql) < 0 THEN
		as_error = "创建'药品信息'对象失败("+ids_typk.is_error+")!"
		RETURN -1
	END IF
END IF
IF Not IsValid(ids_ylsf) THEN
	ids_ylsf = Create U_datastore
	ids_ylsf.setworktrans( itran_sqlca)
	ls_sql = " SELECT FYXH,GJYBBM,fymc,fydw,FYGB,0 AS KZPB,0 AS TSDZ,0 AS LBTSDZ,0 as wgyp,'' as YLMLBM,'' as YLJGMLBM,'' AS MEMO,'' AS MLLB,'' AS SYFYBZ," +&
				" to_date('1900-01-01','yyyy/mm/dd') AS MLKSRQ, to_date('2099-12-31','yyyy/mm/dd') AS MLJSRQ, '' as SFLB, '' as ybmlmc, '' as ybmldj " +&
				"FROM GY_YLSF  "
	IF ids_ylsf.createfromsql(ls_sql) < 0 THEN
		as_error = "创建'费用信息'对象失败("+ids_ylsf.is_error+")!"
		RETURN -1
	END IF
END IF
// //--------特殊对照--类别------------------------------------------
//IF Not IsValid(ids_yb_tsdz_lb) THEN
//	ids_yb_tsdz_lb = Create U_datastore
//	ids_yb_tsdz_lb.setworktrans( itran_sqlca)
//	ls_sql = " SELECT FYLX,FYXH,YBZXBH,TSLB,'' AS GJYBBM FROM JKXT.YB_TSDZ_LB  "
//	IF ids_yb_tsdz_lb.createfromsql(ls_sql) < 0 THEN
//		as_error = "创建'费用信息'对象失败("+ids_yb_tsdz_lb.is_error+")!"
//		RETURN -1
//	ELSE
//		ids_yb_tsdz_lb.SetTransObject(itran_sqlca )
//		ids_yb_tsdz_lb.Retrieve()
//	END IF
//END IF
////----------------------------------------------------------------

Long ll_find,ll_Find_tsdz = 0,ll_count_sl
Integer li_tsdz = 0,li_tsdz_lb = 0
DateTime ldt_brnl,ldt_lnnl,ldt_brnl_6
Date ld_mlksrq, ld_mljsrq
String ls_gjybbm = '',ls_ypmc, ls_yljgmlbm, ls_ylmlbm, ls_temp
String ls_mllb, ls_memo, ls_syfybz, ls_sflb, ls_ybmlmc, ls_ybmldj
IF ai_yplx > 0 THEN //药品
	ll_find = ids_typk.Find(" (ypxh="+String(al_ypxh)+") and (ypcd="+String(al_ypcd)+") and (mlksrq<=date('"+String(Date(adt_jfrq),"yyyy-mm-dd")+"') and date('"+String(Date(adt_jfrq),"yyyy-mm-dd")+"')<=mljsrq)",1,9999999)
	IF ll_find > 0 THEN
		ls_gjybbm = ids_typk.Object.GJYBBM[ll_find]
	ELSE
		Long ll_ypxh,ll_ypcd
		Integer li_zjpb,li_type,li_kzyp,li_wlyp = 0
		Dec{3} ldc_ypjl
		String ls_jldw,ls_yfgg,ls_bfgg,ls_bfdw,ls_yfdw,ls_zxdw
		//AND YK_YPCD.ZFPB=0
		SELECT YK_TYPK.YPXH,YPJL,JLDW,YFGG,BFGG,BFDW,YFDW,ZJPB,TYPE,ZXDW,KZYP,YK_YPCD.YPCD,YK_YPCD.GJYPBM,YPMC
			INTO :ll_ypxh,:ldc_ypjl,:ls_jldw,:ls_yfgg,:ls_bfgg,:ls_bfdw,:ls_yfdw,:li_zjpb,:li_type,:ls_zxdw,:li_kzyp,:ll_ypcd,:ls_gjybbm,:ls_ypmc
			From YPXT.YK_TYPK,YPXT.YK_YPCD Where YK_TYPK.YPXH = :al_ypxh And YK_YPCD.YPXH = YK_TYPK.YPXH And YK_YPCD.YPCD = :al_ypcd and YK_TYPK.ZFPB=0 Using itran_sqlca;
		IF itran_sqlca.SQLCode = 0 THEN
			IF IsNull(ls_gjybbm) THEN ls_gjybbm = ''
			IF Trim(ls_gjybbm) = ''  THEN
				as_error =  ls_ypmc + ':药品未维护对应的国家码，请联系药库维护！' + String(al_ypxh) + "#" + String(al_ypcd)
				RETURN -1
			END IF

			//获取医疗机构目录编码&&医疗目录编码
			ls_yljgmlbm = "Y"+String(ll_ypxh)+"#"+String(ll_ypcd)
			SELECT MED_LIST_CODG, MEMO, LIST_TYPE, begndate, enddate Into :ls_ylmlbm, :ls_memo, :ls_mllb, :ld_mlksrq, :ld_mljsrq From JKXT.ZHYB_MLSB 
			Where FIXMEDINS_HILIST_ID = :ls_yljgmlbm And zfpb = 0 and :adt_jfrq >=BEGNDATE and :adt_jfrq <=ENDDATE Using itran_sqlca;
			IF itran_sqlca.SQLCode = 0 THEN
			ELSEIF itran_sqlca.SQLCode = 100 THEN
				as_error = "药品信息未上报(药品序号：" + String(al_ypxh)+", 药品产地："+String(ll_ypcd)+", 药品名称："+ls_ypmc+")，请联系药库上报！"
				RETURN -1
			ELSE
				as_error = "取不到药品上报信息(药品序号：" + String(al_ypxh)+", 药品产地："+String(ll_ypcd)+", 药品名称："+ls_ypmc+")" + String(itran_sqlca.SQLCode) + itran_sqlca.SQLErrText
				RETURN -1
			END IF
			IF isnull(ls_memo) then ls_memo = ''
			IF isnull(ls_mllb) Then ls_mllb=''
			IF isnull(ld_mlksrq) Then ld_mlksrq = Date(1900,1,1)
			IF isnull(ld_mljsrq) Then ld_mljsrq = Date(2099,12,31)

			// 获取 生覦AT*
�费用标志、开始时间、结束时�

			Select MATN_USED_FLAG, MED_CHRGITM_TYPE, HILIST_NAME, CHRGITM_LV INTO :ls_syfybz, :ls_sflb, :ls_ybmlmc, :ls_ybmldj From JKXT.HILIST_B Where HILIST_CODE=:ls_ylmlbm Using itran_sqlca;
			IF isnull(ls_syfybz) Then ls_syfybz='0'
			IF isnull(ls_sflb) Then ls_sflb=''
			IF isnull(ls_ybmlmc) Then ls_ybmlmc=''
			IF isnull(ls_ybmldj) Then ls_ybmldj=''

			SELECT wlyp Into :li_wlyp From YPXT.yk_typk_kz Where YPXH = :al_ypxh Using itran_sqlca;
			IF IsNull(li_wlyp) THEN li_wlyp = 0
			//			SELECT count(1) Into :li_tsdz From JKXT.YB_TSDZ Where FYLX = 1 And FYXH = :al_ypxh and (ypcd = 0 or ypcd = :al_ypcd) Using itran_sqlca;
			//			SELECT count(1) Into :li_tsdz_lb From JKXT.YB_TSDZ_LB Where FYLX = 1  And FYXH = :al_ypxh Using itran_sqlca;
			ll_find = ids_typk.InsertRow(0)
