			ids_typk.Object.Type[ll_find] = li_type
			ids_typk.Object.ZXDW[ll_find] = ls_zxdw
			ids_typk.Object.KZYP[ll_find] = li_kzyp
			ids_typk.Object.YPCD[ll_find] = ll_ypcd
			ids_typk.Object.GJYBBM[ll_find] = ls_gjybbm
			ids_typk.Object.wgyp[ll_find] = li_wlyp
			ids_typk.Object.YLMLBM[ll_find] = ls_ylmlbm
			ids_typk.Object.YLJGMLBM[ll_find] = ls_yljgmlbm
			ids_typk.Object.MEMO[ll_find] = ls_memo
			ids_typk.Object.MLLB[ll_find] = ls_mllb
			ids_typk.Object.SYFYBZ[ll_find] = ls_syfybz
			ids_typk.Object.MLKSRQ[ll_find] = ld_mlksrq
			ids_typk.Object.MLJSRQ[ll_find] = ld_mljsrq
			ids_typk.Object.SFLB[ll_find] = ls_sflb
			ids_typk.Object.YBMLMC[ll_find] = ls_ybmlmc
			ids_typk.Object.YBMLDJ[ll_find] = ls_ybmldj
			ids_typk.Object.YPMC[ll_find] = ls_ypmc
			//ybfl是否需要？
			IF li_tsdz > 0 THEN
				ids_typk.Object.tsdz[ll_find] = 1
			END IF

			IF li_tsdz_lb > 0 THEN
				ids_typk.Object.lbtsdz[ll_find] = 1
			END IF
		ELSE
			as_error = '取不到药品基本信息:(ypxh:' + String(al_ypxh)+', ypcd:'+String(al_ypcd)+')' + String(itran_sqlca.SQLCode) + itran_sqlca.SQLErrText
			RETURN -1
		END IF

	END IF
ELSE //费用
	ll_find = ids_ylsf.Find(" (fyxh="+String(al_ypxh)+") and (mlksrq<=date('"+String(Date(adt_jfrq),"yyyy-mm-dd")+"') and date('"+String(Date(adt_jfrq),"yyyy-mm-dd")+"')<=mljsrq)",1,9999999)
