			ids_ylsf.Object.FYGB[ll_find] = li_fygb
			ids_ylsf.Object.GJYBBM[ll_find] = ls_gjybbm
			SELECT KZPB Into :li_kzpb From GY_YLSF_KZ Where FYXH = :al_ypxh Using itran_sqlca;
			ids_ylsf.Object.KZPB[ll_find] = li_kzpb
			ids_ylsf.Object.YLMLBM[ll_find] = ls_ylmlbm
			ids_ylsf.Object.YLJGMLBM[ll_find] = ls_yljgmlbm
			ids_ylsf.Object.MEMO[ll_find] = ls_memo
			ids_ylsf.Object.MLLB[ll_find] = ls_mllb
			ids_ylsf.Object.SYFYBZ[ll_find] = ls_syfybz
			ids_ylsf.Object.MLKSRQ[ll_find] = ld_mlksrq
			ids_ylsf.Object.MLJSRQ[ll_find] = ld_mljsrq
			ids_ylsf.Object.SFLB[ll_find] = ls_sflb
			ids_ylsf.Object.YBMLMC[ll_find] = ls_ybmlmc
			ids_ylsf.Object.YBMLDJ[ll_find] = ls_ybmldj
			//ybfl
			IF li_tsdz > 0 THEN
				ids_ylsf.Object.tsdz[ll_find] = 1
			END IF

			IF li_tsdz_lb > 0 THEN
				ids_ylsf.Object.lbtsdz[ll_find] = 1
			END IF

		ELSE
			as_error = '取不到费用基本信息:(fyxh'+String(al_ypxh) +')' + String(itran_sqlca.SQLCode) + itran_sqlca.SQLErrText
			RETURN -1
		END IF

	END IF
END IF
