public function integer uf_mz_mxcx (string jzid, string sfpch, string grbh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.uf_mz_mxcx()
//--------------------------------------------------------------------
// 描述:【2205】门诊费用明细信息撤销
//--------------------------------------------------------------------
// 参数:
// 	value    	string	jzid  	
// 	value    	string	sfpch	
// 	value    	string	grbh    	
// 	reference	string	as_error 	
//--------------------------------------------------------------------
// 返回:  integer
//--------------------------------------------------------------------
// 作者:	sxl		日期: 2022.01.26
//====================================================================
DateTime ldt_now
String ls_czybm
ldt_now = gf_server_date()
IF base_info.syscode = 5 THEN
	ls_czybm = base_info.UserID
	IF This.uf_czy_qrqc( Date(ldt_now), base_info.UserID , 1, as_error) < 0 THEN
		RETURN -1
	END IF
ELSE
	ls_czybm = is_mzzz
	IF This.uf_czy_qrqc( Date(ldt_now),is_mzzz , 1, as_error) < 0 THEN
		RETURN -1
	END IF
END IF

This.uf_send_init( '2205')
istr_jytsrx.insuplc_admdvs = istr_gs_grjbxx.cbdxzqhdm
istr_jytsrx.opter = ls_czybm
This.uf_send_add( 'mdtrt_id', jzid) //ipt_otp_no	门诊/住院流水号
This.uf_send_add( 'chrg_bchno', "") //rxno	处方号	Y	传入"0000"删除所有未结算明细
This.uf_send_add( 'feedetl_sn', "") //feedetl_sn	处方流水号
IF Not uf_send(as_error) THEN
	RETURN -1
ELSE
	//如果撤销成功，更新对应表
END IF
RETURN 1

end function

public function integer uf_tfcl (string as_ywlx, string as_jsid, string as_jydd, datetime adt_yjyjssj, ref str_gs_jsxx astr_gs_jsxx, ref string as_error);//====================================================================
