//====================================================================
// 返回:  integer
//====================================================================

String ls_jzid,ls_grbh,ls_expContent // 就诊ID ,人员编号,字段扩展

Long ll_zyh
String ls_sfybm, ls_cbdybqh,ls_ywlx,ls_jsfl,ls_gbbjdx
DateTime ldt_now
Dec{2} ldc_gbbjzf,ldc_bscje

ldt_now = gf_Server_date()
IF uf_connect_sqlca_temp( ) < 0 THEN
	as_error = "创建临时事务失败！"
	GOTO Error
END IF
DateTime ldt_jssj_00,ldt_jssj_end
ldt_jssj_00 = DateTime(RelativeDate ( Date(adt_yjyjssj), -1 ))
ldt_jssj_end = DateTime(RelativeDate ( Date(adt_yjyjssj), 1 ),Time(adt_yjyjssj))

// 操作员签到
IF base_info.syscode = 5 Or  base_info.syscode = 6 THEN
	ls_sfybm = base_info.UserID
ELSEIF base_info.syscode = 8 THEN
	ls_sfybm = is_zyzz
ELSE
	ls_sfybm = is_mzzz
END IF
IF This.uf_czy_qrqc( Date(ldt_now), ls_sfybm ,  1, Ref as_error) < 0 THEN
	GOTO Error
END IF

// 获取 就诊ID
IF as_ywlx <> 'GH' THEN
	SELECT   JZID,     GRBH,       ZYH,   CBDXZQH,  YWLX ,  NVL(BSCJE,0)
		INTO :ls_jzid, :ls_grbh, :ll_zyh, :ls_cbdybqh,:ls_ywlx,  :ldc_bscje
		FROM JKXT.ZHYB_JSMX
		WHERE JSSJ >= :adt_yjyjssj - 3 AND  JSSJ < :adt_yjyjssj + 3 AND  JSLSH = :as_jsid
		Using itran_sqlca;
	IF itran_sqlca.SQLCode <> 0 THEN
		as_error = "获取原结算明细失败：["+String(itran_sqlca.SQLCode)+"]" + itran_sqlca.SQLErrText
		GOTO Error
	END IF
	IF IsNull(ls_jzid) Or Trim(ls_jzid) = "" THEN
		as_error = "原结算明细的就诊ID为空！结算ID：" + as_jsid
		GOTO Error
	END IF
	IF IsNull(ls_cbdybqh) Or Trim(ls_cbdybqh) = "" THEN
		ls_cbdybqh = istr_gs_grjbxx.cbdxzqhdm

		IF IsNull(ls_cbdybqh) Or Trim(ls_cbdybqh) = "" THEN
			as_error = '参保地行政区划为空，请重新读卡！'
			GOTO Error
		END IF
	END IF
ELSE
	ls_cbdybqh = astr_gs_jsxx.insu_admdvs
	ls_jzid = astr_gs_jsxx.mzyh
	ls_grbh = istr_gs_grjbxx.GRBH
END IF
IF IsNull(ls_grbh) Or Trim(ls_grbh) = "" THEN
	ls_grbh = istr_gs_grjbxx.GRBH
	IF IsNull(ls_grbh) Or Trim(ls_grbh) = "" THEN
		as_error = "人员编号为空，请重新刷卡！"
		GOTO Error
	END IF
END IF
If (IsNull(ll_zyh) Or ll_zyh = 0) And as_ywlx = 'ZY' THEN
	as_error = "原结算明细的住院号为空！结算ID：" + as_jsid
	GOTO Error
END IF


istr_jytsrx.opter = ls_sfybm
istr_jytsrx.insuplc_admdvs = ls_cbdybqh // 修改Header中的"insuplc_admdvs"，以确保参保地一致

This.uf_send_add('mdtrt_id', ls_jzid) // 就诊ID
This.uf_send_add('psn_no', ls_grbh) // 人员编号
This.uf_send_add('exp_content', ls_expContent) // 字段扩展
IF as_ywlx = 'GH' THEN
	This.uf_send_add('ipt_otp_no', as_jsid) // 	住院/门诊号	字符型
ELSE
	This.uf_send_add('setl_id', as_jsid) // 结算ID
END IF


// 发送报文
IF Not This.uf_send(as_error) THEN
	GOTO Error
END IF

