// 获取 病种编码、病种名称
IF IsNull(ls_bzbm) THEN ls_bzbm = ''
IF IsNull(ls_bzmc) THEN ls_bzmc = ''
This.uf_send_init('2201')
istr_jytsrx.opter = ls_czybm // 修改Header中的"opter"，以确保操作员和其签到流水号一致
istr_jytsrx.insuplc_admdvs = ls_cbdybqh // 修改Header中的"insuplc_admdvs"，以确保参保地一致
This.uf_send_add('ipt_otp_no', as_jzid) //1	ipt_otp_no	肈AT*
/住院流水号
This.uf_send_add('med_type', as_rylx) //2	med_type	就诊类别
This.uf_send_add('adm_time', adt_ryrq) //3	adm_time	门诊/住院入院时间 YYYYMMDDHH24MISS
This.uf_send_add('adm_diag_dscr', ls_zzddm) //4	adm_diag_dscr	诊断疾病编码
This.uf_send_add('adm_dept_name', ls_ryksmc) //5	wardarea_name	病区名称
This.uf_send_add('adm_dept_codg', ls_ryksbm) //6	adm_dept_codg	科室编码
This.uf_send_add('adm_bed', as_cwhm) //7	adm_bed	床位号
This.uf_send_add('atddr_no', ls_zzysbm) //8	atddr_no	医生盌AT*

This.uf_send_add('tel', ls_lxdh) //9	tel	病人联系电话
This.uf_send_add('psn_no', ls_grbh) //10	psn_no	个人唯一识别码
This.uf_send_add('ipt_no', as_zyhm) //11	ipt_no	住院号
This.uf_send_add('qualification_id', as_zyhm)//12	qualification_id	工伤医疗费资格 审核信息 ID
//插入登记信息
INSERT INTO JKXT.GS_DJXX(ZYH,MZYH,XLID,	JZLB,		RYSJ,		ZDBM,		BRBQ,		BQKS,			BRCH,		YSBM,			LXDH,GRSBM,ZYHM,DWSBM,        SHID,ZTBZ,CZSJ,CZGH )
VALUES( :al_zyh,:as_jzid,:is_jylsh,:as_rylx,:adt_ryrq,:ls_zzddm,:ll_brbq,:ls_ryksbm,:as_cwhm,:ls_zzysbm,:ls_lxdh,:ls_grbh,,:as_zyhm,:istr_gs_grjbxx.dwwysbm,  	    '',0,sysdate,base_info.userid)	
	 Using itran_sqlca;
IF itran_sqlca.SQLCode = 0 THEN
	COMMIT Using itran_sqlca;
ELSE
	as_error = "工伤新增登记明细失败：["+String(itran_sqlca.SQLCode)+"]"+itran_sqlca.SQLErrText
	ROLLBACK Using itran_sqlca;
	GOTO Error
END IF

IF Not uf_send(Ref as_error) THEN
	GOTO Error
END IF

UPDATE JKXT.GS_DJXX Set ZTBZ = 1 Where ZYH = :al_zyh And ZTBZ = 0 And MZYH = :as_jzid Using itran_sqlca;
IF itran_sqlca.SQLCode = 0 THEN
	COMMIT Using itran_sqlca;
ELSE
	as_error = "【医保端】入院办理成功，但作废原入院登记明细失败，请联系信息科处理。住院号码："+as_zyhm+" 错误信息：["+String(itran_sqlca.SQLCode)+"]"+itran_sqlca.SQLErrText
	ROLLBACK Using itran_sqlca;
	GOTO Error_ybRollBack
END IF
// 2.更新 BQXT.ZY_BRRY.JSDH
IF ab_commit THEN
	gf_begin_transaction(atr_trans)
END IF
IF ll_jsdh > 1 THEN
	UPDATE BQXT.ZY_BRRY Set jsdh = :ll_jsdh Where ZYH = :al_zyh Using atr_trans;
	IF ab_commit THEN
		IF atr_trans.SQLCode = 0 THEN gf_commit_transaction(atr_trans)
	END IF
ELSE
	UPDATE BQXT.ZY_BRRY Set jsdh = 1 Where ZYH = :al_zyh Using atr_trans;
END IF
// 3.更新ZY_BRRY_KZ.YBJZBH，并删除住院预结信息和作废上传的费用明细
INSERT Into BQXT.ZY_BRRY_KZ("ZYH","YBJZBH") Values(:al_zyh,:as_jzid) Using atr_trans;
UPDATE BQXT.ZY_BRRY_KZ Set YBJZBH = :as_jzid Where ZYH = :al_zyh Using atr_trans;
IF atr_trans.SQLCode = 0 THEN
	DELETE From JKXT.yb_zyyjxx Where ZYH = :al_zyh Using itran_sqlca;
	IF itran_sqlca.SQLCode = 0 THEN
		gf_commit_transaction(itran_sqlca)
	ELSE
		gf_rollback_transaction(itran_sqlca)
	END IF
	SELECT count(1) Into :ll_count From JKXT.GS_FYMXSC  Where ZYH = :al_zyh And ZTBZ In (0,9,-2) Using itran_sqlca;
	IF ll_count > 0 THEN
		UPDATE JKXT.GS_FYMXSC Set ZTBZ = -1 Where ZYH = :al_zyh And ZTBZ In (0,9,-2)  Using itran_sqlca;
	END IF
	IF ab_commit THEN gf_commit_transaction(atr_trans)
END IF
RETURN 1
Error_ybRollBack:
DateTime ldt_temp
String ls_error_jyzf
// 调用“交易作废”，作废本次入院办理
IF This.uf_jyzf( ldt_temp, '2201', ls_grbh, is_jylsh, Ref ls_error_jyzf) < 0 THEN
	as_error = as_error + ls_error_jyzf
END IF

Error:
as_error = "[2201-入院登记]出错：" + as_error
RETURN -1
end function

public function integer uf_zydj (ref string as_knsj, long al_ksdm, long al_zyh, datetime adt_ryrq, string as_zyhm, string as_cwhm, string as_bahm, string as_ysbm, string as_rylx, ref string as_jzbh, ref string as_error);//====================================================================
// 事件: u_zhyl_his.uf_zydj()
//--------------------------------------------------------------------
// 描述: 病区住院登记最终入口
//--------------------------------------------------------------------
// 参数:
// 	reference	string  	as_knsj 	
// 	value    	long    	al_ksdm 	
// 	value    	long    	al_zyh  	
// 	value    	datetime	adt_ryrq	
// 	value    	string  	as_zyhm 	
// 	value    	string  	as_cwhm 	
// 	value    	string  	as_bahm 	
// 	value    	string  	as_ysbm 	
// 	reference	string  	as_jzbh 	
// 	reference	string  	as_error	
