	ldt_ryrq = ldt_jsrq
ELSE
	SELECT BQRYSJ Into :ldt_rysj From ZY_BRRY_KZ Where ZYH = :al_zyh Using sqlca;
	IF Not IsNull(ldt_rysj) And sqlca.SQLCode = 0 THEN
		ldt_ryrq = ldt_rysj
	END IF
END IF

RETURN uf_zydj(ref ls_knsj, ll_ksdm, al_zyh, ldt_ryrq, ls_zyhm, ls_brch, ls_bahm, ls_ysbm, '1', ref as_jzbh, ref as_error)

end function

