public function integer of_lgzy (integer ai_lglx, datetime adt_bqcrjsj, long al_zyh, transaction atran_sqlca);String ls_brbm,ls_pid,ls_pid_brbm
SELECT brbm,pid Into :ls_brbm,:ls_pid From bqxt.zy_brry Where zyh = :al_zyh Using atran_sqlca;
IF ls_brbm > ' ' THEN
	SELECT pid Into :ls_pid_brbm From mz_brda Where brbm = :ls_brbm Using atran_sqlca;
END IF
IF IsNull(ls_pid_brbm) Or Trim(ls_pid_brbm) = '' THEN ls_pid_brbm = ls_pid
//没有pid对应brbm也没有pid那么就返回
IF IsNull(ls_pid)  Or Trim(ls_pid) = '' Or IsNull(ls_pid_brbm) Or Trim(ls_pid_brbm)  = ''  THEN RETURN 0
//普通病区入院前24小时是否有留观的出院记录，有则走急诊住院否则普通住院,排除床管
Long ll_count = 0
IF ai_lglx = 1 THEN //普通病区判断是否有留观住院
	SELECT COUNT(1) INTO :ll_count
		FROM BQXT.ZY_BRRY B,BQXT.ZY_BRRY_KZ K
		WHERE B.ZYH = K.ZYH AND instr(:is_lgks,','||to_char(B.BRBQ) ||',') > 0 AND B.CYPB >= 0 AND B.CYPB <= 9 AND B.BRBQ <> :il_yzybq
		And K.BQCYSJ <= :adt_bqcrjsj + 0.25 And K.BQCYSJ >= :adt_bqcrjsj - 1 And (B.pid = :ls_pid Or B.pid = :ls_pid_brbm) Using atran_sqlca;
	//pid对应的brbm
	//IF ll_count = 0 THEN
	//	SELECT COUNT(1) INTO :ll_count
	//	FROM BQXT.ZY_BRRY B,BQXT.ZY_BRRY_KZ K
	//		WHERE B.ZYH = K.ZYH AND instr(:is_lgks,','||to_char(B.BRBQ) ||',') > 0 AND B.CYPB >= 0 AND B.CYPB <= 9 AND B.BRBQ <> :il_yzybq
	//		AND K.BQCYSJ <= :adt_bqrjsj + 0.25 AND K.BQCYSJ >= :adt_bqrjsj - 1 AND
	//		B.brbm In (SELECT mz_brda.brbm From mz_brda Where mz_brda.pid = :ls_pid_brbm Or mz_brda.pid = :ls_pid ) Using atran_sqlca;
	//END IF
ELSEIF ai_lglx = 2 THEN //留观判断是否有后续住院
	 SELECT COUNT(1) INTO :ll_count
		FROM BQXT.ZY_BRRY B,BQXT.ZY_BRRY_KZ K
		WHERE B.ZYH = K.ZYH AND B.BRBQ in (select ksdm from xtgl.gy_ksdm where rypb = 0) AND B.CYPB >= 0 AND B.CYPB <= 9 AND B.BRBQ <> :il_yzybq
		And K.BQRYSJ >= :adt_bqcrjsj - 0.25 And K.BQRYSJ <= :adt_bqcrjsj + 1 And (B.pid = :ls_pid Or B.pid = :ls_pid_brbm) 
		AND K.BQRYSJ is not null Using atran_sqlca;
END IF
RETURN ll_count



end function
